#!/usr/bin/env python3
"""Smart Irrigation System for Raspberry Pi.

Controls a solenoid valve via gpiozero on BCM GPIO 17, reads a capacitive
moisture sensor on MCP3008 SPI ADC on CE0, and serves a JSON API over TCP.
"""

import argparse
import logging
import signal
import sys
import time

import spidev
from gpiozero import DigitalOutputDevice

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
DEFAULT_MOISTURE_THRESHOLD = 30
DEFAULT_WEB_PORT = 8080
DEFAULT_LOG_FILE = "irrigation.log"
DEFAULT_VALVE_PIN = 17
DEFAULT_SPI_CHANNEL = 0

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    filename=DEFAULT_LOG_FILE,
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_valve = None
_spi = None
_spi_dev = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    logger.info("Signal %s received – shutting down …", signum)
    _running = False


def _cleanup():
    """Release all hardware resources."""
    global _valve, _spi, _spi_dev
    if _valve is not None:
        try:
            _valve.close()
        except Exception:
            pass
        _valve = None
    if _spi is not None:
        try:
            _spi.close()
        except Exception:
            pass
        _spi = None
    if _spi_dev is not None:
        try:
            _spi_dev.close()
        except Exception:
            pass
        _spi_dev = None


def _read_moisture(spi_dev, channel):
    """Read a single-ended channel from the MCP3008.

    Returns (value, error) or (None, None) on failure.
    """
    if channel < 0 or channel > 7:
        logger.error("Invalid SPI channel %d", channel)
        return None, "Invalid channel"
    if spi_dev is None:
        logger.error("SPI device not initialized")
        return None, "SPI device not open"

    try:
        # MCP3008 single-ended read: start bit, config byte, then read bits
        # Byte 0: 0x01 (start)
        # Byte 1: (0x08 | channel) << 4  (single-ended, channel bits)
        # Byte 2: 0x00 (don't care)
        # Byte 3: 0x00 (don't care)
        response = spi_dev.xfer2([0x01, (0x08 | channel) << 4, 0x00])
        # Response is 3 bytes: low byte, middle byte, high byte
        value = ((response[1] & 0x03) << 8) | response[2]
        return value
    except Exception as exc:
        logger.error("SPI read error on channel %d: %s", channel, exc)
        return None, "SPI read error"


def _read_all_moisture():
    """Read all three channels of the MCP3008 and return a list of values."""
    values = []
    for ch in range(3):
        value = _read_moisture(spi_dev, ch)
        if value is not None:
            values.append(value)
        else:
            values.append(None)
    return values


def _calculate_moisture(values):
    """Return moisture percentage (0-100) from a list of three values."""
    if len(values) < 3:
        logger.error("Incomplete moisture reading: %s", values)
        return None
    if all(v is None for v in values):
        logger.warning("All moisture readings are None – skipping")
        return None
    if all(v < 0 or v > 100 for v in values):
        logger.warning("Moisture values out of range [0, 100] – skipping")
        return None
    return sum(values) / len(values) * 100.0


def _calculate_threshold(moisture_threshold):
    """Return a hysteresis threshold (percentage) for the valve."""
    return moisture_threshold + 10.0


def _calculate_valve_state(moisture, valve_pin, threshold):
    """Return True when the valve is active, False when it is closed."""
    if moisture is None:
        return False
    return (moisture < threshold) and (moisture < threshold + 10.0)


def _calculate_valve_state_with_threshold(moisture, valve_pin, threshold):
    """Return True when the valve is active, False when it is closed."""
    if moisture is None:
        return False
    return (moisture < threshold) and (moisture < threshold + 10.0) and (
        _calculate_valve_state(moisture, valve_pin, threshold)
    )


def _calculate_valve_state_with_threshold_and_hysteresis(
    moisture, valve_pin, threshold, hysteresis
):
    """Return True when the valve is active, False when it is closed."""
    if moisture is None:
        return False
    if _calculate_valve_state(moisture, valve_pin, threshold):
        return True
    if _calculate_valve_state(moisture, valve_pin, threshold + hysteresis):
        return True
    return False


def _calculate_valve_state_with_threshold_and_hysteresis_and_hysteresis(
    moisture, valve_pin, threshold, hysteresis, valve_state
):
    """Return True when the valve is active, False when it is closed."""
    if moisture is None:
        return False
    if _calculate_valve_state_with_threshold(moisture, valve_pin, threshold):
        return True
    if _calculate_valve_state_with_threshold_and_hysteresis(
        moisture, valve_pin, threshold, hysteresis
    ):
        return True
    if _calculate_valve_state_with_threshold_and_hysteresis(
        moisture, valve_pin, threshold + hysteresis, hysteresis
    ):
        return True
    return False


def _calculate_valve_state_with_threshold_and_hysteresis_and_hysteresis_and_hysteresis(
    moisture, valve_pin, threshold, hysteresis, valve_state, valve_state_prev
