                    time.sleep(1)
                    continue

                accel_x, accel_y, accel_z = read_accel()
                mag_x, mag_y, mag_z = read_mag()
                heading = read_heading()

                duty_cycle = int(adc_val * ADC_MAX / ADC_GAIN)
                control_motor(duty_cycle)

                print(f"ADC={adc_val}, Accel={accel_x}, Accel={accel_y}, Accel={accel_z}, "
                      f"Mag={mag_x}, Mag={mag_y}, Mag={mag_z}, Heading={heading:.2f}")

            except Exception as e:
                print(f"Error in main loop: {e}")
                time.sleep(1)

            time.sleep(1)
