import time
import logging
import signal
import sys
import queue
import spidev
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.running = True
        self.spi = None
        self.gpio_setup()
        self.setup_logging()
        self.setup_queue()
        self.setup_signal_handlers()
        self.setup_spi()
        self.setup_gpio()
        self.setup_sound_sensor()

    def setup_logging(self):
        logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

    def setup_queue(self):
        if self.log_queue is None:
            self.log_queue = queue.Queue()

    def setup_signal_handlers(self):
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

    def setup_signal_handler(self):
        pass

    def setup_spi(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = self.spi_speed
            self.spi.mode = 0
            logging.info(f"SPI initialized: bus 0, device 0, speed {self.spi_speed} Hz")
        except Exception as e:
            logging.error(f"Failed to initialize SPI: {e}")
            self.spi = None

    def setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(self.gpio_pins, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            logging.info(f"GPIO initialized: pins {self.gpio_pins}")
        except Exception as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            self.spi = None

    def setup_sound_sensor(self):
        if self.spi is None:
            logging.error("SPI not initialized, cannot setup sound sensor")
            return
        try:
            if self.sensor_type == 'digital':
                GPIO.setup(self.gpio_pins, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
                logging.info(f"Digital sound sensor initialized on GPIO {self.gpio_pins}")
            else:
                logging.error(f"Unsupported sensor type: {self.sensor_type}")
                return
            logging.info(f"Sound sensor initialized: {self.sensor_id}")
        except Exception as e:
            logging.error(f"Failed to setup sound sensor: {e}")

    def read_sound_level(self, channel):
        if self.spi is None:
            logging.error("SPI not initialized, cannot read sound level")
            return None
        try:
            if self.sensor_type == 'digital':
                if channel < 0 or channel > 7:
                    logging.error(f"Invalid channel {channel}, must be 0-7")
                    return None
                GPIO.output(self.gpio_pins, GPIO.LOW)
                time.sleep(0.1)
                GPIO.output(self.gpio_pins, GPIO.HIGH)
                time.sleep(0.1)
                return GPIO.input(self.gpio_pins)
            else:
                if channel < 0 or channel > 7:
                    logging.error(f"Invalid channel {channel}, must be 0-7")
                    return None
                adc_value = self.spi.xfer2([1, (8 + channel) << 4, 0])
                if len(adc_value) < 3:
                    logging.error(f"SPI read returned incomplete data: {adc_value}")
                    return None
                adc_value = adc_value[1]
                if adc_value >= 0x1000:
                    logging.warning(f"ADC value {adc_value} exceeds threshold {self.threshold}")
                    return None
                return adc_value
        except Exception as e:
            logging.error(f"Error reading sound level from channel {channel}: {e}")
            return None

    def run(self):
        logging.info(f"SoundSensor running. Press Ctrl+C to stop.")
        while self.running:
            try:
                sound_level = self.read_sound_level(self.channels)
                if sound_level is not None:
                    logging.info(f"Sound level: {sound_level}")
                    self.log_queue.put(sound_level)
                time.sleep(self.sample_rate)
            except Exception as e:
                logging.error(f"Error in run loop: {e}")
                time.sleep(1)

    def stop(self):
        self.running = False
        logging.info("Stopping SoundSensor...")
        if self.spi:
            try:
                self.spi.close()
                logging.info("SPI closed.")
            except Exception as e:
                logging.error(f"Error closing SPI: {e}")
        if self.gpio_setup:
            try:
                GPIO.cleanup()
                logging.info("GPIO cleaned up.")
            except Exception as e:
                logging.error(f"Error cleaning GPIO: {e}")
        logging.info("SoundSensor stopped.")

    def cleanup(self):
        self.stop()

def main():
    sensor_id = "sound_sensor_1"
    sensor_type = "digital"
    threshold = 100
    sample_rate = 1000
    gpio_pins = [0, 1, 2, 3, 4, 5, 6, 7]
    channels = [0, 1, 2, 3, 4, 5, 6, 7]
    spi_speed = 1000000
    log_queue = None
    sensor = None

    try:
        sensor = SoundSensor(sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed, log_queue)
        sensor.run()
    except Exception as e:
        logging.error(f"Fatal error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

