import spidev
import time
import signal
import sys
import logging
from collections import deque

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# --- Configuration ---
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1000000
ADC_CHANNEL = 0
OVER_CURRENT_THRESHOLD = 15.0
OVER_CURRENT_SAMPLES = 20
SAMPLE_INTERVAL = 1.0

# --- Globals for cleanup ---
spi = None
relay_pin = None
running = True

def signal_handler(signum, frame):
    global running
    logging.info(f"Signal {signum} received, shutting down...")
    running = False

def init_spi():
    global spi
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        logging.info("SPI initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Failed to initialize SPI: {e}")
        return False

def init_relay():
    global relay_pin
    try:
        relay_pin = int(sys.argv[1])
        logging.info(f"Relay GPIO pin set to BCM {relay_pin}.")
        return True
    except Exception as e:
        logging.error(f"Failed to set relay GPIO pin: {e}")
        return False

def read_adc(channel):
    if not 0 <= channel <= 7:
        logging.error(f"Invalid ADC channel: {channel}")
        return None
    try:
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data
    except OSError as e:
        logging.error(f"SPI transfer error on channel {channel}: {e}")
        return None

def convert_to_rms(raw_value):
    if raw_value is None:
        return None
    try:
        adc_value = raw_value / 1023.0
        rms_value = adc_value * (30.0 / 1023.0)
        return rms_value
    except Exception as e:
        logging.error(f"Error converting ADC value: {e}")
        return None

def detect_over_current(rms_current):
    if rms_current is None:
        return False
    try:
        if rms_current > OVER_CURRENT_THRESHOLD:
            logging.warning(f"Over-current detected: {rms_current:.2f}A")
            return True
        return False
    except Exception as e:
        logging.error(f"Error detecting over-current: {e}")
        return False

def update_trend(rms_current, last_trend):
    if rms_current is None:
        return last_trend
    try:
        new_trend = deque(maxlen=OVER_CURRENT_SAMPLES)
        new_trend.append(rms_current)
        return list(new_trend)[:OVER_CURRENT_SAMPLES]
    except Exception as e:
        logging.error(f"Error updating trend: {e}")
        return last_trend

def cleanup():
    global spi, relay_pin
    logging.info("Cleaning up resources...")
    if relay_pin is not None:
        try:
            relay_pin.off()
            relay_pin.close()
            logging.info("Relay GPIO pin released.")
        except Exception as e:
            logging.error(f"Error releasing relay GPIO: {e}")
    if spi is not None:
        try:
            spi.close()
            logging.info("SPI closed.")
        except Exception as e:
            logging.error(f"Error closing SPI: {e}")
    logging.info("Cleanup complete.")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not init_spi():
        sys.exit(1)
    if not init_relay():
        cleanup()
        sys.exit(1)

    logging.info("Starting energy monitoring...")
    trend_buffer = deque(maxlen=OVER_CURRENT_SAMPLES)

    for i in range(8):
        if not running:
            break
        try:
            current_sample = read_adc(ADC_CHANNEL)
            if current_sample is not None:
                rms_current = convert_to_rms(current_sample)
                if detect_over_current(rms_current):
                    logging.warning(f"Over-current detected on channel {ADC_CHANNEL}.")
                    if relay_pin is not None:
                        relay_pin.off()
                        time.sleep(0.5)
                        relay_pin.on()
                        time.sleep(0.5)
                        relay_pin.off()
                else:
                    trend_buffer.append(rms_current)
                    logging.info(f"Current RMS: {rms_current:.2f}A")
                    if len(trend_buffer) > OVER_CURRENT_SAMPLES:
                        trend_buffer.popleft()
                time.sleep(SAMPLE_INTERVAL)
            else:
                logging.warning(f"Failed to read ADC on channel {ADC_CHANNEL}.")
        except OSError as e:
            logging.error(f"SPI transfer error on channel {ADC_CHANNEL}: {e}")
            time.sleep(SAMPLE_INTERVAL)
        except Exception as e:
            logging.error(f"Unexpected error during sampling: {e}")
            time.sleep(SAMPLE_INTERVAL)

    cleanup()
    logging.info("Energy monitoring complete.")

if __name__ == "__main__":
    main()

