import numpy as np
import signal
import sys
from picamera2 import Picamera2

running = True

def signal_handler(sig, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    cameras = []
    try:
        cameras.append(Picamera2(camera_num=0))
        cameras.append(Picamera2(camera_num=1))
    except Exception as e:
        print(f"Error initializing cameras: {e}", file=sys.stderr)
        return

    try:
        while running:
            try:
                frame0 = cameras[0].capture_array()
                frame1 = cameras[1].capture_array()
            except Exception as e:
                print(f"Error capturing frame from camera {camera_num}: {e}", file=sys.stderr)
                continue

            if frame0 is None or frame1 is None:
                print("Warning: empty frame received from camera", file=sys.stderr)
                continue

            combined = np.hstack((frame0, frame1))
            cv2.imshow('Dual CSI Cameras', combined)

            key = cv2.waitKey(30) & 0xFF
            if key == 27:
                print("ESC pressed, exiting...")
                break
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        for cam in cameras:
            try:
                cam.stop()
            except Exception:
                pass
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

