import RPi.GPIO as GPIO
import time
import datetime
import speech_recognition as sr
import adafruit_dht
import board
import signal
import sys

# GPIO pin for the DHT11 sensor (BCM numbering)
DHT_PIN = 4

# GPIO pin for the lights (BCM numbering)
LIGHTS_PIN = 17

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False

def cleanup_resources():
    """Clean up GPIO and camera resources."""
    try:
        GPIO.cleanup()
    except Exception:
        pass
    try:
        camera.stop()
    except Exception:
        pass

def read_temperature():
    """Reads temperature from the DHT11 sensor.

    Returns:
        float: Temperature in Celsius.
    """
    try:
        sensor = adafruit_dht.DHT11(board.D4)
        temperature = sensor.temperature
        return temperature
    except Exception as e:
        print(f"Error reading temperature: {e}")
        return None

def read_light_status():
    """Reads the status of the lights.

    Returns:
        bool: True if lights are on, False if lights are off.
    """
    try:
        return GPIO.input(LIGHTS_PIN)
    except Exception as e:
        print(f"Error reading light status: {e}")
        return False

def turn_lights_on():
    """Turns the lights on."""
    GPIO.output(LIGHTS_PIN, GPIO.HIGH)
    print("Lights turned on")

def turn_lights_off():
    """Turns the lights off."""
    GPIO.output(LIGHTS_PIN, GPIO.LOW)
    print("Lights turned off")

def get_temperature():
    """Gets the current temperature.

    Returns:
        float: Temperature in Celsius.
    """
    temperature = read_temperature()
    if temperature is not None:
        return temperature
    return None

def get_light_status():
    """Gets the current light status.

    Returns:
        bool: True if lights are on, False if lights are off.
    """
    return read_light_status()

def take_picture():
    """Takes a picture using the PiCamera2.

    Returns:
        str: The path to the saved image file.
    """
    try:
        camera = picamera2.Picamera2()
        config = camera.create_still_configuration(main={"size": (640, 480)})
        camera.configure(config)
        camera.start()
        time.sleep(2)  # Allow camera to warm up
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        camera.capture_file(filename)
        camera.stop()
        print(f"Picture saved: {filename}")
        return filename
    except Exception as e:
        print(f"Error taking picture: {e}")
        return None

def main():
    """Main function to run the greenhouse control system."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LIGHTS_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Failed to initialize GPIO: {e}")
        cleanup_resources()
        sys.exit(1)

    try:
        recognizer = sr.Recognizer()
        with sr.Microphone() as source:
            recognizer.adjust_for_ambient_noise(source, duration=0.5)
            print("Say 'Greenhouse' to start the greenhouse system.")
            audio = recognizer.listen(source, timeout=5)
    except Exception as e:
        print(f"Failed to initialize speech recognition: {e}")
        GPIO.cleanup()
        cleanup_resources()
        sys.exit(1)

    try:
        while running:
            try:
                temperature = get_temperature()
                light_status = get_light_status()
                print(f"Temperature: {temperature}°C")
                print(f"Light status: {light_status}")

                if temperature is not None and light_status:
                    if temperature > 30:
                        turn_lights_on()
                    elif temperature < 15:
                        turn_lights_off()
                    else:
                        print("Temperature is within safe range.")
                else:
                    print("Temperature or light status is invalid.")

                if "turn on the lights" in audio.lower():
                    turn_lights_on()
                elif "turn off the lights" in audio.lower():
                    turn_lights_off()
                elif "what is the temperature" in audio.lower():
                    print(f"Temperature: {temperature}°C")
                elif "take a picture" in audio.lower():
                    filename = take_picture()
                    if filename:
                        print(f"Picture saved: {filename}")
                    else:
                        print("Failed to save picture.")
                else:
                    print("Invalid command. Please try again.")

            except sr.UnknownValueError:
                print("Could not understand audio. Please try again.")
            except sr.RequestError as e:
                print(f"Could not request results from speech recognition service. {e}")
            except Exception as e:
                print(f"An unexpected error occurred: {e}")

            time.sleep(1)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup_resources()

if __name__ == "__main__":
    main()

