#!/usr/bin/env python3
"""
Raspberry Pi 4-wire PWM fan controller.

Controls a 4-wire PWM fan (or a 3-wire fan driven via a logic-level MOSFET)
on GPIO 17 (BCM) using gpiozero's PWMOutputDevice.  Reads CPU temperature
from /sys/class/thermal/thermal_zone0/temp and applies a descending
threshold-to-duty-cycle mapping.  On startup, sets the fan to 1.0 (full
speed) before throttling back.  PWM values are validated and range
[0.0, 1.0].  Errors during PWMOutputDevice initialization, temperature
reading, or PWM writing are logged and handled via exit with a non-zero
status.

Dependencies:
    - gpiozero (pip install gpiozero)
    - python3-sysfs (sudo apt install python3-sysfs)

Usage:
    sudo systemctl start fan_control.service
    sudo systemctl stop fan_control.service
"""

import sys
import time
import signal
import logging
from pathlib import Path

from gpiozero import PWMOutputDevice

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
