#!/usr/bin/env python3
"""
Continuous polling of digital inputs and driving of two outputs on a Raspberry Pi.
Uses gpiozero for modern GPIO access with robust error handling and resource cleanup.
"""

import signal
import sys
import time

try:
    from gpiozero import Button, OutputDevice, LED
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
INPUT_PINS = [4, 5, 6]          # BCM GPIO numbers
OUTPUT_PINS = [23, 24]         # BCM GPIO numbers
POLL_INTERVAL = 0.05           # seconds between polls

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_inputs = []
_outputs = []
_running = True


def _cleanup():
    """Release all GPIO resources cleanly."""
    global _inputs, _outputs
    for dev in _inputs + _outputs:
        try:
            dev.close()
        except Exception:
            pass
    _inputs.clear()
    _outputs.clear()


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _init_gpio():
    """Initialize all GPIO pins as outputs with internal pull-ups enabled."""
    global _inputs, _outputs
    try:
        for pin in INPUT_PINS:
            _inputs.append(Button(pin, pull_up=True))
        for pin in OUTPUT_PINS:
            _outputs.append(OutputDevice(pin))
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error initializing GPIO: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error during GPIO init: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)


def _poll_inputs():
    """Return a list of LOW-level events detected by the inputs."""
    events = []
    for pin in INPUT_PINS:
        if not _running:
            return events
        try:
            if not _inputs[pin].is_active:
                events.append(pin)
        except Exception as exc:
            print(f"Warning: error reading input pin {pin}: {exc}", file=sys.stderr)
    return events


def _drive_outputs(outputs):
    """Drive each output to the LOW state."""
    for pin in outputs:
        try:
            pin.off()
        except Exception as exc:
            print(f"Warning: error driving output pin {pin}: {exc}", file=sys.stderr)


def _toggle_output(pin):
    """Toggle the logical state of a single output pin."""
    try:
        if pin.is_active:
            pin.off()
        else:
            pin.on()
    except Exception as exc:
        print(f"Warning: error toggling output pin {pin}: {exc}", file=sys.stderr)


def main():
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _init_gpio()

    try:
        while _running:
            events = _poll_inputs()
            for event in events:
                if event not in _inputs:
                    continue
                if _inputs[event].is_active:
                    _outputs[event].on()
                else:
                    _outputs[event].off()
            _toggle_output(_outputs[4])
            _toggle_output(_outputs[5])
            _toggle_output(_outputs[6])
            time.sleep(POLL_INTERVAL)
    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

