    """Initialize all GPIO pins as outputs with internal pull-ups enabled."""
    global _inputs, _outputs
    try:
        for pin in INPUT_PINS:
            _inputs.append(Button(pin, pull_up=True))
        for pin in OUTPUT_PINS:
