import serial
import serial.tools.list_ports
import sys
import signal

SERIAL_PORT = '/dev/rfcomm4'
BAUD_RATE = 38400

running = True

def signal_handler(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, bytesize=8,
                             parity=serial.PARITY_NONE,
                             stopbits=serial.STOPBITS_ONE,
                             timeout=1)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                user_input = input('Enter text to send over Bluetooth (q to quit): ')
            except EOFError:
                break

            if not user_input:
                continue

            user_input = user_input.strip()
            if not user_input:
                continue

            try:
                ser.write(user_input.encode('utf-8'))
                ser.flush()
                print(f'Sent: {len(user_input)} bytes')
            except serial.SerialException as e:
                print(f"Error sending data: {e}", file=sys.stderr)
                break
    finally:
        try:
            ser.close()
            print('Serial port closed.')
        except serial.SerialException:
            pass

if __name__ == '__main__':
    main()

