import serial
import time
import signal
import sys
import numpy as np
from picamera2 import Picamera2

# Constants
SERIAL_PORT = '/dev/ttyACM0'
SERIAL_BAUDRATE = 9600
SERIAL_TIMEOUT = 1
OBJECT_AREA_THRESHOLD = 500
COLOR_RANGE_DEADZONE = 50

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False

def initialize_camera():
    """Initializes the Raspberry Pi Camera Module using picamera2."""
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)})
        picam2.configure(config)
        picam2.start()
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def initialize_serial(port, baudrate):
    """Initializes the serial connection with error handling."""
    try:
        ser = serial.Serial(port, baudrate, timeout=SERIAL_TIMEOUT)
        return ser
    except serial.SerialException as e:
        print(f"Error initializing serial port: {e}")
        return None

def process_frame(frame, color_range_deadzone):
    """Processes a frame to identify objects and their color range."""
    hsv_frame = frame.astype("float") / 255.0
    hsv_frame = np.clip(hsv_frame, 0, 1)

    # HSV color range for object detection
    lower_hsv = np.array([0, color_range_deadzone, 0])
    upper_hsv = np.array([180, color_range_deadzone, 255])

    mask = np.zeros_like(hsv_frame)
    mask[hsv_frame >= lower_hsv] = 1
    mask[hsv_frame <= upper_hsv] = 0

    # Find contours
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

    # Process each contour
    for contour in contours:
        area = cv2.contourArea(contour)
        if area > OBJECT_AREA_THRESHOLD:
            x, y, w, h = cv2.boundingRect(contour)
            cv2.rectangle(frame, (x, y), (x + w, y + h), (0, 255, 0), 2)

            # Find center
            center_x = x + w / 2
            center_y = y + h / 2

            # Determine object type based on center relative to frame center
            if center_x > frame.shape[1] / 2 and center_y > frame.shape[0] / 2:
                if center_x < frame.shape[1] / 2 - color_range_deadzone and center_y < frame.shape[0] / 2 - color_range_deadzone:
                    return 1, center_x, center_y
                elif center_x > frame.shape[1] / 2 + color_range_deadzone and center_y > frame.shape[0] / 2 + color_range_deadzone:
                    return 2, center_x, center_y
                elif center_x < frame.shape[1] / 2 and center_y < frame.shape[0] / 2 + color_range_deadzone:
                    return 3, center_x, center_y
                elif center_x > frame.shape[1] / 2 + color_range_deadzone and center_y < frame.shape[0] / 2 + color_range_deadzone:
                    return 4, center_x, center_y
            else:
                if center_x < frame.shape[1] / 2 - color_range_deadzone and center_y < frame.shape[0] / 2 - color_range_deadzone:
                    return 5, center_x, center_y
                elif center_x > frame.shape[1] / 2 + color_range_deadzone and center_y < frame.shape[0] / 2 + color_range_deadzone:
                    return 6, center_x, center_y
                elif center_x < frame.shape[1] / 2 and center_y < frame.shape[0] / 2 + color_range_deadzone:
                    return 7, center_x, center_y
                elif center_x > frame.shape[1] / 2 + color_range_deadzone and center_y < frame.shape[0] / 2 + color_range_deadzone:
                    return 8, center_x, center_y

    return None, None, None

def send_serial_data(ser, color_range_deadzone):
    """Sends serial data to the Raspberry Pi."""
    try:
        if color_range_deadzone > 0:
            ser.write(b'1')
        else:
            ser.write(b'0')
    except serial.SerialException as e:
        print(f"Error sending serial data: {e}")

def main():
    global running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    picam2 = initialize_camera()
    if picam2 is None:
        print("Failed to initialize camera. Exiting.")
        sys.exit(1)

    ser = initialize_serial(SERIAL_PORT, SERIAL_BAUDRATE)
    if ser is None:
        print("Failed to initialize serial port. Exiting.")
        picam2.close()
        sys.exit(1)

    try:
        while running:
            frame = picam2.capture_array()
            if frame is None:
                print("Failed to capture frame.")
                break

            color_range_deadzone = COLOR_RANGE_DEADZONE

            # Process frame
            color_range, center_x, center_y = process_frame(frame, color_range_deadzone)

            if color_range:
                send_serial_data(ser, color_range_deadzone)

            # Display original frame and color mask
            cv2.imshow('Original Frame', frame)
            cv2.imshow('Color Mask', color_range)

            # Check for 's' to sample center
            if cv2.waitKey(1) & 0xFF == ord('s'):
                # Sample 100x100 region for color range
                sample_region = frame[100:200, 100:200]
                hsv_sample = cv2.cvtColor(sample_region, cv2.COLOR_BGR2HSV)
                color_range_sample = np.zeros_like(hsv_sample)
                color_range_sample[hsv_sample >= np.array([0, 0, 0])] = 255
                color_range_sample[hsv_sample <= np.array([180, 180, 180])] = 0

                # Determine object type based on center relative to frame center
                if center_x > frame.shape[1] / 2 and center_y > frame.shape[0] / 2:
                    if center_x < frame.shape[1] / 2 - color_range_deadzone and center_y < frame.shape[0] / 2 - color_range_deadzone:
                        send_serial_data(ser, color_range_deadzone)
                elif center_x > frame.shape[1] / 2 + color_range_deadzone and center_y > frame.shape[0] / 2 + color_range_deadzone:
                    send_serial_data(ser, color_range_deadzone)
                elif center_x < frame.shape[1] / 2 and center_y < frame.shape[0] / 2 + color_range_deadzone:
                    send_serial_data(ser, color_range_deadzone)
                elif center_x > frame.shape[1] / 2 + color_range_deadzone and center_y < frame.shape[0] / 2 + color_range_deadzone:
                    send_serial_data(ser, color_range_deadzone)

            # Check for ESC (27) to exit
            if cv2.waitKey(1) & 0xFF == 27:
                break
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        # Cleanup resources
        if ser is not None:
            try:
                ser.close()
            except serial.SerialException:
                pass
        if picam2 is not None:
            try:
                picam2.stop()
            except Exception:
                pass
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

