from picamera2 import Picamera2

running = True

def signal_handler(sig, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def main():
    global running
    picam2 = None
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(main={"size": (640, 480), "format": "RGB888"})
        picam2.configure(config)
        picam2.start()
        print("Camera initialized successfully.")
    except Exception as e:
        print(f"Error initializing camera: {e}")
        sys.exit(1)

    try:
        while running:
            try:
                frame = picam2.capture_array()
                if frame is None:
                    print("Warning: captured empty frame, skipping.")
                    continue

                gray = cv2.cvtColor(frame, cv2.COLOR_RGB2GRAY)
                faces = cv2.CascadeClassifier('haarcascade_frontalface_default.xml').detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))

                for (x, y, w, h) in faces:
                    cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)
                    cv2.imshow('Face Detection', frame)

                    if cv2.waitKey(1) & 0xFF == ord('q'):
                        break

                if len(faces) > 0:
                    filename = f"images/face_{time.strftime('%Y%m%d_%H%M%S')}.jpg"
                    success = cv2.imwrite(filename, frame)
                    if success:
                        print(f"Saved image: {filename}")
                    else:
                        print(f"Error saving image: {filename}")
                else:
                    print("No faces detected.")
            except Exception as e:
                print(f"Error during frame capture/processing: {e}")
                break
    finally:
        if picam2 is not None:
            try:
                picam2.stop()
                print("Camera stopped.")
            except Exception as e:
                print(f"Error stopping camera: {e}")
        cv2.destroyAllWindows()
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

