import asyncio
import signal
import threading
import logging
import cv2
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import JpegEncoder
from picamera2.outputs import Output
from typing import Callable, Optional

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

BUFFER_LOCK = threading.Lock()

class WebSocketHandler:
    def __init__(self, detect_motion_callback: Callable[[np.ndarray, np.ndarray], None],
                 on_connected: Optional[Callable[[], None]] = None,
                 on_disconnected: Optional[Callable[[], None]] = None):
        self.detect_motion_callback = detect_motion_callback
        self.on_connected = on_connected
        self.on_disconnected = on_disconnected
        self.connected = False
        self.buffer: Optional[np.ndarray] = None
        self.lock = BUFFER_LOCK

    def broadcast(self, data: bytes) -> None:
        if not self.connected:
            logger.debug("WebSocketHandler: on_disconnected called, no connections yet.")
            return
        with BUFFER_LOCK:
            if self.buffer is None:
                return
            try:
                self.buffer = np.frombuffer(data, dtype=np.uint8)
            except Exception as e:
                logger.error(f"Error decoding JPEG data: {e}")
                return
        if self.buffer is None:
            return
        try:
            if self.on_connected:
                self.on_connected()
        except Exception as e:
            logger.error(f"Error on connected callback: {e}")

    def has_connections(self) -> bool:
        with BUFFER_LOCK:
            return self.buffer is not None

class MotionDetector:
    def __init__(self, detect_motion_callback: Callable[[np.ndarray, np.ndarray], None],
                 on_connected: Optional[Callable[[], None]] = None,
                 on_disconnected: Optional[Callable[[], None]] = None):
        self.detect_motion_callback = detect_motion_callback
        self.on_connected = on_connected
        self.on_disconnected = on_disconnected
        self.connected = False
        self.lock = BUFFER_LOCK

    def broadcast(self, data: bytes) -> None:
        if not self.connected:
            logger.debug("MotionDetector: on_disconnected called, no connections yet.")
            return
        with BUFFER_LOCK:
            if self.buffer is None:
                return
            try:
                self.buffer = np.frombuffer(data, dtype=np.uint8)
            except Exception as e:
                logger.error(f"Error decoding JPEG data: {e}")
                return
        if self.buffer is None:
            return
        try:
            if self.on_connected:
                self.on_connected()
        except Exception as e:
            logger.error(f"Error on connected callback: {e}")

    def detect_motion(self, prev_frame: np.ndarray, curr_frame: np.ndarray) -> None:
        if prev_frame is None or curr_frame is None:
