class WebSocketHandler:
    def __init__(self, detect_motion_callback: Callable[[np.ndarray, np.ndarray], None],
                 on_connected: Optional[Callable[[], None]] = None,
                 on_disconnected: Optional[Callable[[], None]] = None):
        self.detect_motion_callback = detect_motion_callback
        self.on_connected = on_connected
        self.on_disconnected = on_disconnected
        self.connected = False
        self.buffer: Optional[np.ndarray] = None
        self.lock = BUFFER_LOCK

    def broadcast(self, data: bytes) -> None:
        if not self.connected:
            logger.debug("WebSocketHandler: on_disconnected called, no connections yet.")
            return
        with BUFFER_LOCK:
            if self.buffer is None:
                return
            try:
                self.buffer = np.frombuffer(data, dtype=np.uint8)
            except Exception as e:
                logger.error(f"Error decoding JPEG data: {e}")
                return
        if self.buffer is None:
            return
        try:
            if self.on_connected:
                self.on_connected()
        except Exception as e:
            logger.error(f"Error on connected callback: {e}")

    def has_connections(self) -> bool:
        with BUFFER_LOCK:
            return self.buffer is not None

