class MotionDetectionBuffer:
    """
    A buffer that receives JPEG frames from a camera and detects motion
    by detecting the \xff\xd8 marker that marks the start of a new JPEG image.
    """

    def __init__(self, camera: Picamera2, detect_motion_function: Callable[[np.ndarray, np.ndarray], None]):
        self.camera = camera
        self.detect_motion_function = detect_motion_function
        self.buffer: io.BytesIO = io.BytesIO()
        self.previous_frame: np.ndarray = None
        self.current_frame: np.ndarray = None
        self.lock = threading.Lock()
        self._running = True

        try:
            self.camera.configure(
                self.camera.create_preview_configuration(
                    main={"size": (640, 480), "format": "RGB888"}
                )
            )
            self.camera.start()
            logger.info("Camera started successfully.")
        except Exception as e:
            logger.error(f"Failed to start camera: {e}")
            raise

    def write(self, data: bytes) -> None:
        """
        Write raw JPEG data to the buffer.
        """
        if not self.buffer.write(data):
            logger.error("Failed to write data to buffer.")
            return
        self.lock.acquire()
        try:
            self.buffer.seek(0)
            self.buffer.truncate()
            self.buffer.write(data)
        finally:
            self.lock.release()

    def _detect_motion(self, previous_frame: np.ndarray, current_frame: np.ndarray) -> None:
