RIGHT_PWM_FREQUENCY = 50  # Hz

BALL_X = 180
BALL_Y = -200

GOAL_X = 0
GOAL_Y = 200

EXTENSION = 50

CAR_FRONT_X = 180
CAR_FRONT_Y = -15
CAR_BACK_X = 200
CAR_BACK_Y = -15

CAR_FRONT_DISTANCE = 10
CAR_BACK_DISTANCE = 10

CAR_HEADING_X = CAR_FRONT_X
CAR_HEADING_Y = CAR_FRONT_Y
CAR_BACK_HEADING_X = CAR_BACK_X
CAR_BACK_HEADING_Y = CAR_BACK_Y

ANGLE_THRESHOLD = 175
ANGLE_DISTANCE_THRESHOLD = 10

MAX_ITERATIONS = 1000

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_left_motor = None
_right_motor = None


def _signal_handler(signum, frame):
    global _running
    _running = False


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


def compute_image_point(ball, goal, extension):
    """Return a point beyond the ball on the line from ball to goal."""
    x = ball[0] + (goal[0] - ball[0]) * (goal[0] - ball[0]) / (goal[0] - ball[0])
    y = ball[1] + (goal[1] - ball[1]) * (goal[1] - ball[1]) / (goal[1] - ball[1])
    return (x, y)


def compute_car_heading(front, back):
    """Return the car's heading (X, Y) from front to back."""
    return (front[0] - back[0], front[1] - back[1])


def compute_distance(front, back):
    """Return the distance from front to back."""
    return (front[0] - back[0]) ** 2 + (front[1] - back[1]) ** 2


def compute_angle(heading):
    """Return the angle in degrees (0-360)."""
    return (heading[0] - 180.0) % 360.0


def compute_angle_difference(heading1, heading2):
    """Return the angle difference in degrees (0-180)."""
    return abs(heading1[0] - heading2[0]) % 360.0


def compute_distance_difference(distance1, distance2):
    """Return the distance difference in meters."""
    return abs(distance1 - distance2)


def compute_angle_difference_distance(angle1, angle2, distance1, distance2):
    """Return True if the angle difference is greater than the distance difference."""
    return compute_angle_difference(angle1, angle2) > ANGLE_DISTANCE_THRESHOLD or \
        compute_distance_difference(distance1, distance2) > DISTANCE_THRESHOLD


def compute_car_speed(front, back):
    """Return the car's speed (0-1)."""
    return (front[0] - back[0]) / (front[0] - back[0])


def compute_car_heading_speed(front, back):
    """Return the car's heading and speed."""
    heading = compute_car_heading(front, back)
    speed = compute_car_speed(front, back)
    return heading, speed


def compute_car_distance(front, back):
    """Return the distance from front to back."""
    return compute_distance(front, back)


def compute_car_distance_to_goal(front, back):
    """Return the distance from front to goal."""
    return compute_distance(front, back)


def compute_car_angle(front, back):
    """Return the car's angle from front to back."""
    return compute_angle(front)


