import smbus2
import time
import signal
import sys

# I2C bus and PCF8574 address
I2C_BUS = 1
PCF8574_ADDR = 0x20

# Proximity sensor pins (active-low)
SENSOR_PINS = [0, 1, 2, 3, 4, 5, 6, 7]

# PCF8574 output port register (bit 0 = pull-up enabled)
OUTPUT_PORT = 0x00

# Global bus handle for signal handler
bus = None
running = True

def signal_handler(sig, frame):
    """Handle Ctrl-C gracefully."""
    global running
    print("\nInterrupt received, shutting down...")
    running = False

def read_proximity_sensor(bus, sensor_pin):
    """Read the current state of a proximity sensor (0=LOW, 1=HIGH)."""
    try:
        # Read the output port (bit 0 = pull-up enabled)
        value = bus.read_byte_data(PCF8574_ADDR, OUTPUT_PORT)
        # Check if pull-up is enabled (bit 0 = 1)
        if value & 0x01:
            return 1.0
        else:
            return 0.0
    except OSError as e:
        print(f"I2C bus error reading sensor {sensor_pin}: {e}")
        return None

def main():
    global bus

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)

    # Initialize I2C bus
    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    # Initialize all proximity sensors as inputs with pull-up enabled
    for pin in SENSOR_PINS:
        try:
            # Set pull-up to enable
            bus.write_byte_data(PCF8574_ADDR, OUTPUT_PORT, 0xFF)
            # Read current state to confirm
            current_state = read_proximity_sensor(bus, pin)
            if current_state is None:
                print(f"Warning: Sensor {pin} returned None (sensor absent or error)")
            else:
                print(f"Sensor {pin} reading LOW (pull-up enabled)")
        except OSError as e:
            print(f"I2C bus error setting up sensor {pin}: {e}")
            # Attempt to recover by clearing pull-up and re-setting
            try:
                bus.write_byte_data(PCF8574_ADDR, OUTPUT_PORT, 0x00)
                current_state = read_proximity_sensor(bus, pin)
                if current_state is None:
                    print(f"Warning: Sensor {pin} returned None (sensor absent or error)")
                else:
                    print(f"Sensor {pin} reading HIGH (pull-up cleared)")
            except OSError as recover_e:
                print(f"Failed to recover sensor {pin}: {recover_e}")

    # Main polling loop
    try:
        while running:
            for pin in SENSOR_PINS:
                current_state = read_proximity_sensor(bus, pin)
                if current_state is None:
                    print(f"Warning: Sensor {pin} returned None (sensor absent or error)")
                else:
                    print(f"Sensor {pin} reading LOW (pull-up enabled)")

            # Wait 100ms, but check running flag every iteration
            for _ in range(100):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        # Clean resource release on all exit paths
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

