#!/usr/bin/env python3
"""Hydroponics controller using gpiozero and TCP socket server."""

import argparse
import logging
import socket
import sys
import time
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# Constants
DHT_PIN = 4
RELAY_PIN = 17
LOG_FILE = "hydroponics.log"

# Global state
relay = None
dht_sensor = None
server_socket = None

def setup_logging():
    """Configure logging to file and console."""
    logging.basicConfig(
        filename=LOG_FILE,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s'
    )
    console = logging.StreamHandler()
    console.setLevel(logging.INFO)
    console.setFormatter(logging.Formatter('%(asctime)s - %(levelname)s - %(message)s'))
    logging.getLogger().addHandler(console)

def setup_gpio():
    """Initialize GPIO pins and relay."""
    global relay
    try:
        relay = OutputDevice(RELAY_PIN, active_high=True, initial_value=False)
        logging.info(f"Relay pin {RELAY_PIN} initialized as output (OFF).")
    except GPIOZeroError as e:
        logging.error(f"GPIO setup failed: {e}")
        sys.exit(1)

def setup_dht():
    """Simulate reading DHT11 sensor on GPIO4."""
    global dht_sensor
    try:
        dht_sensor = DHT11(DHT_PIN)
        logging.info(f"DHT11 sensor initialized on GPIO4.")
    except Exception as e:
        logging.error(f"DHT11 init failed: {e}")
        dht_sensor = None

def get_status():
    """Return current pump state and temperature."""
    if relay is None:
        return {"pump": "off", "temperature": 25.0}
    try:
        if relay.is_active:
            return {"pump": "on", "temperature": 25.0}
        else:
            return {"pump": "off", "temperature": 25.0}
    except DeviceClosed:
        logging.error("Relay device closed during get_status.")
        return {"pump": "off", "temperature": 25.0}
    except GPIOZeroError as e:
        logging.error(f"GPIO error during get_status: {e}")
        return {"pump": "off", "temperature": 25.0}

def handle_command(command):
    """Handle JSON command from client."""
    if not isinstance(command, dict):
        logging.error(f"Invalid command format: {command}")
        return
    command_type = command.get("command")
    if command_type == "pump_on":
        relay.on()
        logging.info("Pump turned ON.")
    elif command_type == "pump_off":
        relay.off()
        logging.info("Pump turned OFF.")
    elif command_type == "get_status":
        status = get_status()
        response = {"pump": status["pump"], "temperature": status["temperature"]}
        logging.info(f"Status: {response}")
        return response
    else:
        logging.error(f"Unknown command: {command}")
        return None

def handle_client(client_socket):
    """Handle incoming TCP client connection."""
    try:
        while True:
            try:
                data = client_socket.recv(1024).decode("utf-8")
                if not data:
                    break
                command = data.strip()
                if command:
                    response = handle_command(command)
                    if response:
                        client_socket.sendall(json.dumps(response).encode("utf-8"))
            except socket.timeout:
                pass
            except Exception as e:
                logging.error(f"Socket error during client: {e}")
                break
    except Exception as e:
        logging.error(f"Socket error during client loop: {e}")
    finally:
        if client_socket:
            client_socket.close()
            logging.info("Client socket closed.")

def main():
    """Main entry point."""
    parser = argparse.ArgumentParser(description="Hydroponics Controller")
    parser.add_argument("--relay_pin", type=int, default=RELAY_PIN, help="GPIO pin for relay (BCM)")
    parser.add_argument("--dht_pin", type=int, default=DHT_PIN, help="GPIO pin for DHT11 (BCM)")
    parser.add_argument("--port", type=int, default=12345, help="TCP port (default: 12345)")
    parser.add_argument("--ip", type=str, default="192.168.1.100", help="Allowed IP address (default: 192.168.1.100)")
    parser.add_argument("--log_file", type=str, default=LOG_FILE, help="Log file path (default: hydroponics.log)")
    args = parser.parse_args()

    setup_logging()
    logging.info("Hydroponics controller started.")

    try:
        setup_gpio()
        setup_dht()
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((args.ip, args.port))
        server_socket.listen(1)
        server_socket.settimeout(5)
        logging.info(f"Server listening on {args.ip}:{args.port}")
        while True:
            try:
                client_socket, client_address = server_socket.accept()
                logging.info(f"Connected by {client_address}")
                handle_client(client_socket)
            except socket.timeout:
                pass
    except KeyboardInterrupt:
        logging.info("Hydroponics controller stopped by user.")
    except GPIOZeroError as e:
        logging.error(f"GPIO error: {e}")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if relay:
            relay.close()
            logging.info("Relay GPIO closed.")
        if dht_sensor:
            dht_sensor.exit()
        logging.info("GPIO and DHT cleanup complete.")

if __name__ == "__main__":
    main()

