import serial
import signal
import sys
import time

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1

running = True

def handle_signal(signum, frame):
    global running
    running = False

def validate_temperature(temp):
    return -40 <= temp <= 85

def validate_humidity(hum):
    return 0 <= hum <= 100

def validate_pressure(pres):
    return 800 <= pres <= 1200

def read_weather_data(serial_port):
    try:
        with serial_port as ser:
            while running:
                try:
                    raw = ser.readline()
                except serial.SerialException as e:
                    print(f"Serial read error: {e}", file=sys.stderr)
                    break

                if not raw:
                    continue

                line = raw.decode("ascii", errors="replace").strip()
                if not line:
                    continue

                parts = line.split(",")
                if len(parts) != 3:
                    print(f"Malformed line: {line!r}", file=sys.stderr)
                    continue

                temp, hum, pres = parts
                if not validate_temperature(temp):
                    print(f"Temperature out of range: {temp!r}", file=sys.stderr)
                    continue
                if not validate_humidity(hum):
                    print(f"Humidity out of range: {hum!r}", file=sys.stderr)
                    continue
                if not validate_pressure(pres):
                    print(f"Pressure out of range: {pres!r}", file=sys.stderr)
                    continue

                timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                print(f"{timestamp} - Temperature: {temp:.1f} C, Humidity: {hum:.1f} %, Pressure: {pres:.1f} hPa")
    except Exception as e:
        print(f"Error reading serial data: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")
        read_weather_data(ser)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

