import serial
import time
import csv
import signal
import sys

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1
LOG_FILE = 'temperature_log.csv'

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_temperature(ser):
    """Read one line from the serial port and return Celsius, or None on error."""
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS error reading serial port: {e}", file=sys.stderr)
        return None

    if not raw:
        return None

    line = raw.decode('ascii', errors='replace').strip()
    if not line:
        return None

    try:
        temp_str = line.strip()
        if not temp_str.startswith('C'):
            return None
        return float(temp_str)
    except ValueError:
        return None

def log_temperature(timestamp, celsius, fahrenheit):
    """Append one row to the CSV log file."""
    try:
        with open(LOG_FILE, 'a', newline='') as f:
            writer = csv.writer(f)
            writer.writerow([timestamp, fahrenheit, f'{celsius:.1f}'])
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")

        while _running:
            temp = read_temperature(ser)
            if temp is not None:
                log_temperature(time.strftime('%Y-%m-%d %H:%M:%S'), temp, temp * 9/5 + 32)
            time.sleep(0.1)

    except serial.SerialException as e:
        print(f"Serial port error: {e}", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"OS error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

