#!/usr/bin/env python3
"""
Greenhouse monitoring and control system for Raspberry Pi.

Reads DHT22 sensor on GPIO4 every 60 s, logs simulated data,
maintains 5-minute moving average, and triggers actuators on
threshold crossings.  Simulates sensor failures and actuator control.
"""

import json
import logging
import signal
import sys
import time
import urllib.request

import adafruit_dht
import board

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "webhook_url": "http://localhost:5000/webhook",
    "temperature_threshold": 30.0,
    "humidity_threshold": 80.0,
    "vent_fan_delay": 300,
    "water_pump_delay": 300,
    "heater_delay": 300,
    "sensor_pin": 4,
    "sample_rate": 60,
    "max_samples": 5,
    "fail_count": 3,
    "fail_delay": 300,
    "log_level": "INFO",
    "log_file": "greenhouse.log",
}

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
    handlers=[
        logging.FileHandler(CONFIG_FILE),
        logging.StreamHandler(sys.stdout),
    ],
)
logger = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
_running = True
_dht_device = None
_sensor_pin = None


def load_config(config_file=CONFIG_FILE):
    """Load configuration from JSON file, fall back to defaults."""
    try:
        with open(config_file, "r") as f:
            cfg = json.load(f)
        logger.info("Loaded configuration from %s", config_file)
        return cfg
    except FileNotFoundError:
        logger.warning("Config file %s not found; using defaults", config_file)
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as exc:
        logger.error("Invalid JSON in %s: %s", config_file, exc)
        return DEFAULT_CONFIG.copy()


def validate_config(cfg):
    """Validate sensor pin, sample rate, and fail-count."""
    if not isinstance(cfg["sensor_pin"], int) or cfg["sensor_pin"] < 1:
        logger.error("sensor_pin must be an integer >= 1")
        return False
    if cfg["sample_rate"] <= 0:
        logger.error("sample_rate must be > 0")
        return False
    if cfg["fail_count"] < 1:
        logger.error("fail_count must be > 0")
        return False
    if cfg["fail_delay"] < 0:
        logger.error("fail_delay must be >= 0")
        return False
    return True


def read_dht22(pin):
    """Read temperature and humidity from DHT22 on GPIO4 (BCM)."""
    global _dht_device
    if _dht_device is not None:
        try:
            temp = _dht_device.temperature
            hum = _dht_device.humidity
            if temp is not None and hum is not None:
                if -40 <= temp <= 80:
                    if 0 <= hum <= 100:
                        return temp, hum
                    else:
                        logger.warning("DHT22 Humidity out of range: %.1f", hum)
                else:
                    logger.warning("DHT22 Temperature out of range: %.1f", temp)
        except RuntimeError as exc:
            logger.warning("DHT22 read error: %s", exc)
        except Exception as exc:
            logger.error("Unexpected DHT22 error: %s", exc)
    # Simulate: 20-30°C, 60-80%
    temp = 20.0 + (30.0 * (random.random() * 0.1))
    hum = 60.0 + (80.0 * (random.random() * 0.1))
    logger.info("Simulated DHT22: temp=%.1f°C, hum=%.1f%%", temp, hum)
    return temp, hum


def simulate_sensor_data():
    """Return (temperature, humidity) with plausible errors."""
    temp = 20.0 + (30.0 * (random.random() * 0.1))
    hum = 60.0 + (80.0 * (random.random() * 0.1))
    logger.warning("Simulated DHT22: temp=%.1f°C, hum=%.1f%%", temp, hum)
    return temp, hum


def validate_readings(temp, hum):
    """Return True if both readings are within valid ranges."""
    if temp is None or hum is None:
