import RPi.GPIO as GPIO
import time
import datetime
import sqlite3
import csv
import logging
import http.server
import threading
import urllib.parse
import urllib.request
import os
import signal
import sys

# Configuration
DHT_PIN = 4
DB_FILE = "greenhouse_data.db"
CSV_FILE = "greenhouse_data.csv"
SERVER_PORT = 8080
SERVER_HOST = "0.0.0.0"
SERVER_BACKGROUND_THREADS = 10
RETRY_DELAY = 1
RETRY_MAX_RETRIES = 3
RETRY_BACKOFF = 1

# Global state
running = True
lock = threading.Lock()

def signal_handler(sig, frame):
    global running
    logging.info("Shutdown signal received. Cleaning up...")
    running = False

def init_logging():
    logging.basicConfig(
        filename='greenhouse.log',
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s'
    )

def init_database():
    try:
        conn = sqlite3.connect(DB_FILE)
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp TEXT PRIMARY KEY,
                temperature REAL,
                humidity REAL
            )
        ''')
        conn.commit()
        logging.info("Database initialized successfully.")
        return conn
    except sqlite3.Error as e:
        logging.error(f"Database initialization failed: {e}")
        return None

def init_sensor():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DHT_PIN, GPIO.IN)
        logging.info("GPIO initialized successfully.")
        return DHT_PIN
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        return None

def read_dht22(sensor_pin):
    try:
        for attempt in range(RETRY_MAX_RETRIES):
            try:
                temperature = sensor_pin.read_temperature()
                humidity = sensor_pin.read_humidity()
                if temperature is not None and humidity is not None:
                    return temperature, humidity
                else:
                    logging.warning(f"DHT22 returned None on attempt {attempt + 1}")
            except Exception as e:
                logging.error(f"DHT22 read error on attempt {attempt + 1}: {e}")
                time.sleep(RETRY_DELAY)
        logging.warning("DHT22 read failed after all retries.")
        return None, None
    except Exception as e:
        logging.error(f"DHT22 initialization failed: {e}")
        return None, None

def simulate_greenhouse_data():
    temperature = 20.0 + (time.time() % 2) * 2.0
    humidity = 40.0 + (time.time() % 2) * 5.0
    return temperature, humidity

def store_data(conn, timestamp, temperature, humidity):
    try:
        cursor = conn.cursor()
        cursor.execute(
            "INSERT INTO sensor_data (timestamp, temperature, humidity) VALUES (?, ?, ?)",
            (timestamp, temperature, humidity)
        )
        conn.commit()
    except sqlite3.Error as e:
        logging.error(f"Database insert failed: {e}")

def export_data(conn, filename):
    try:
        timestamp = datetime.datetime.now().isoformat()
        with open(filename, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([timestamp, 'Temperature', 'Humidity'])
            for row in conn.execute('SELECT * FROM sensor_data'):
                writer.writerow(row)
    except Exception as e:
        logging.error(f"CSV export failed: {e}")

def export_data_24h(conn, filename):
    try:
        timestamp = datetime.datetime.now().isoformat()
        with open(filename, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([timestamp, 'Temperature', 'Humidity'])
            for row in conn.execute('SELECT * FROM sensor_data'):
                writer.writerow(row)
        os.remove(filename)
    except Exception as e:
        logging.error(f"24h export failed: {e}")

def http_server(port):
    def handle_request(request):
        if request.method == 'GET':
            if request.path == '/':
                return '<!DOCTYPE html><html><body><h1>Greenhouse Data</h1><table border="1"><tr><th>Timestamp</th><th>Temperature</th><th>Humidity</th></tr>'
            elif request.path == '/data':
                with lock:
                    if not running:
                        return 'Server is currently unavailable.'
                    conn = init_database()
                    if conn:
                        timestamp = datetime.datetime.now().isoformat()
                        temperature, humidity = read_dht22(DHT_PIN)
                        if temperature is not None and humidity is not None:
                            store_data(conn, timestamp, temperature, humidity)
                            export_data(conn, CSV_FILE)
                            export_data_24h(conn, CSV_FILE)
                            logging.info(f"Data exported to {CSV_FILE}")
                        else:
                            logging.warning("Simulated data stored, but sensor read failed.")
                        conn.close()
                    else:
                        logging.warning("Database connection failed.")
            elif request.path == '/export':
                with lock:
                    if not running:
                        return 'Server is currently unavailable.'
                    conn = init_database()
                    if conn:
                        timestamp = datetime.datetime.now().isoformat()
                        with open(CSV_FILE, 'a', newline='') as csvfile:
                            writer = csv.writer(csvfile)
                            writer.writerow([timestamp, 'Temperature', 'Humidity'])
                            for row in conn.execute('SELECT * FROM sensor_data'):
                                writer.writerow(row)
                        conn.close()
                    else:
                        logging.warning("Database connection failed.")
            else:
                return 'Invalid path'
        else:
            return '404 Not Found'
    return http.server.SimpleHTTPRequestHandler(
        port=port,
        log_format='%(method)s %s %s %s',
        log_format_version=2,
        path_used_count=0
    )

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    init_logging()
    conn = init_database()
    sensor_pin = init_sensor()

    server_thread = threading.Thread(target=http_server, args=(SERVER_PORT,), daemon=True)
    server_thread.start()

    try:
        while running:
            with lock:
                if not running:
                    break
                timestamp = datetime.datetime.now().isoformat()
                temperature, humidity = simulate_greenhouse_data()
                if temperature is not None and humidity is not None:
                    logging.info(f"Simulated data: {timestamp}, Temp: {temperature:.2f}C, Humidity: {humidity:.2f}%")
                else:
                    logging.warning("Simulated data: {timestamp}, Temp: None, Humidity: None".format(timestamp=timestamp))
            time.sleep(60)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        server_thread.join(timeout=5)
        GPIO.cleanup()
        logging.info("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

