    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        # Clean resource release on all exit paths
        try:
            sensor.exit()
        except Exception:
            pass
        print("Sensor resources released. Exiting.")

if __name__ == "__main__":
    main()

