import time
import signal
import sys
import board
import busio
import adafruit_bmp280

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False

def main():
    global running

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize I2C bus
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        sys.exit(1)

    # Initialize BMP280 sensor at I2C address 0x76 (or 0x77 on some breakouts)
    try:
        sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c, address=0x76)
    except ValueError as e:
        print(f"Error: BMP280 not found at I2C address 0x76: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Error initializing BMP280: {e}")
        sys.exit(1)

    # Establish baseline pressure
    baseline_pressure = None
    try:
        for i in range(10):
            if not running:
                break
            try:
                baseline_pressure = sensor.pressure
                if baseline_pressure is None:
                    print("Warning: Baseline pressure read failed, skipping this reading.")
                else:
                    print(f"Baseline pressure: {baseline_pressure:.2f} hPa")
                time.sleep(1)
            except OSError as e:
                print(f"Error reading baseline pressure: {e}")
                break
    except OSError as e:
        print(f"Error reading baseline pressure: {e}")
    finally:
        if baseline_pressure is not None:
            print(f"Baseline pressure: {baseline_pressure:.2f} hPa")

    # Main loop: continuously read and display altitude
    try:
        while running:
            try:
                altitude = sensor.altitude
                if altitude is None:
                    print("Warning: Altitude read failed, skipping this reading.")
                else:
                    print(f"Altitude: {altitude:.2f} meters")
            except OSError as e:
                print(f"Error reading altitude: {e}")
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        # Clean up resources
        try:
            i2c.deinit()
        except Exception:
            pass
        print("Program finished.")

if __name__ == "__main__":
    main()

