import adafruit_dht
import requests

# Configuration
DHT_PIN = board.D4  # GPIO4 (physical pin 7)
SERVER_URL = "http://127.0.0.1:5000/data"
READ_INTERVAL = 5  # seconds

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def get_temperature_humidity(sensor):
    """Read temperature and humidity from the DHT11 sensor.
    Returns (temperature, humidity) or (None, None) on failure."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is not None and humidity is not None:
            return temperature, humidity
        return None, None
    except RuntimeError as e:
        # DHT11 often throws transient read errors; retry on the next cycle
        return None, None
    except Exception as e:
        print(f"Unexpected error reading DHT11: {e}")
        return None, None

def send_data(temperature, humidity):
    """Send a JSON payload with temperature and humidity to the server."""
    payload = {"temperature": temperature, "humidity": humidity}
    try:
        response = requests.post(SERVER_URL, json=payload, timeout=10)
        response.raise_for_status()
        print(f"Data sent successfully. Status code: {response.status_code}")
    except requests.exceptions.Timeout:
        print("Error: Request timed out.")
    except requests.exceptions.ConnectionError as e:
        print(f"Error: Connection failed: {e}")
    except requests.exceptions.HTTPError as e:
        print(f"Error: HTTP error {e.response.status_code}: {e.response.text}")
    except requests.exceptions.RequestException as e:
        print(f"Error: Request failed: {e}")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize DHT11 sensor
    try:
        sensor = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Fatal: Failed to initialize DHT11 sensor: {e}")
        sys.exit(1)

    print("Starting DHT11 monitoring. Press Ctrl+C to stop.")

    try:
        while _running:
            temperature, humidity = get_temperature_humidity(sensor)

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                send_data(temperature, humidity)
            else:
                print("Skipping this cycle due to sensor read failure.")

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < READ_INTERVAL:
                time.sleep(0.1)
                slept += 0.1

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        # Clean resource release on every exit path
        try:
            sensor.exit()
        except Exception:
            pass
        print("Resources released. Exiting.")

if __name__ == "__main__":
    main()

