import signal
import sys
import time
import logging
import paho.mqtt.client as mqtt
from paho.mqtt.client import CallbackAPIVersion

import adafruit_dht
import board

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
CONFIG = {
    'dhtgpiopin': board.D22,          # BCM GPIO 22 (physical pin 7)
    'mqttbroker': 'localhost',
    'mqttport': 1883,
    'mqttusername': 'homie',
    'mqttpassword': 'secret',
    'homieclientid': 'rpi_dht22',
    'homienodes': 'temperature',
    'publishtime': 5,
    'mqttretry': 3,
    'mqttretrydelay': 2,
}

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
)
log = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_dht_device = None
_mqtt_client = None


def _signal_handler(signum, frame):
    global _running
    log.info('Signal %s received – shutting down …', signum)
    _running = False


def _cleanup():
    global _dht_device, _mqtt_client
    if _mqtt_client is not None:
        try:
            _mqtt_client.loop_stop()
        except Exception:
            pass
        try:
            _mqtt_client.disconnect()
        except Exception:
            pass
        _mqtt_client = None
    if _dht_device is not None:
        try:
            _dht_device.exit()
        except Exception:
            pass
        _dht_device = None


def _publish_mqtt(client, topic, payload, qos):
    if client is None:
        return
    try:
        client.publish(topic, payload, qos=qos)
    except Exception as exc:
        log.error('MQTT publish failed on %s/%s: %s', topic, payload, exc)


def _read_dht22(device):
    """Read temperature and humidity from the DHT22 with retries."""
    for attempt in range(CONFIG['mqttretry']):
        try:
            temperature = device.temperature
            humidity = device.humidity
            if temperature is not None and humidity is not None:
                log.info('DHT22: %.1f °C  %.1f %%')
                return temperature, humidity
            else:
                log.warning('DHT22: returned None (attempt %d)', attempt + 1)
        except RuntimeError as exc:
            log.warning('DHT22: read error (attempt %d): %s', attempt + 1, exc)
        except Exception as exc:
            log.error('DHT22: unexpected error (attempt %d): %s', attempt + 1, exc)
        if attempt < CONFIG['mqttretry'] - 1:
            time.sleep(CONFIG['mqttretrydelay'])
    log.error('DHT22: failed after %d retries', CONFIG['mqttretry'])
    return None, None


def _publish_mqtt_with_retry(client, topic, payload, qos):
    for attempt in range(CONFIG['mqttretry']):
        try:
            _publish_mqtt(client, topic, payload, qos)
            return
        except Exception as exc:
            log.warning('MQTT publish failed on %s/%s: %s', topic, payload, exc)
            if attempt < CONFIG['mqttretry'] - 1:
                time.sleep(CONFIG['mqttretrydelay'])
    log.error('MQTT publish failed after %d retries', CONFIG['mqttretry'])


def main():
    global _dht_device, _mqtt_client

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _dht_device = adafruit_dht.DHT22(CONFIG['dhtgpiopin'], use_pulseio=False)
    _mqtt_client = mqtt.Client(
        callback_api_version=CallbackAPIVersion.VERSION2,
        client_id=CONFIG['homieclientid'],
    )

    _mqtt_client.on_connect = _mqtt_client.on_connect
    _mqtt_client.on_disconnect = _mqtt_client.on_disconnect
    _mqtt_client.on_message = _mqtt_client.on_message

    _mqtt_client.connect(CONFIG['mqttbroker'], CONFIG['mqttport'], keepalive=60)
    _mqtt_client.loop_start()

    try:
        while _running:
            temperature, humidity = _read_dht22(_dht_device)
            if temperature is not None and humidity is not None:
                _publish_mqtt_with_retry(_mqtt_client, f'homie/{CONFIG["homieclientid"]}/{CONFIG["homienodes"]}/temperature',
                                         f'{temperature:.1f}', 1)
                _publish_mqtt_with_retry(_mqtt_client, f'homie/{CONFIG["homieclientid"]}/{CONFIG["homienodes"]}/humidity',
                                         f'{humidity:.1f}', 1)
            else:
                log.warning('DHT22 read failed – retrying in %d s', CONFIG['publishtime'])
                time.sleep(CONFIG['publishtime'])
    finally:
        _cleanup()


if __name__ == '__main__':
    main()

