import random
import time
import signal
import sys

try:
    from gpiozero import DigitalOutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

FAN_PIN = 18
TEMP_MIN = 20
TEMP_MAX = 40
FAN_THRESHOLD = 30
READINGS = 5
PAUSE_SECONDS = 2

fan = None
running = True

def signal_handler(signum, frame):
    global running
    running = False

def get_temperature():
    return random.randint(TEMP_MIN, TEMP_MAX)

def control_fan(temp, fan):
    if temp > FAN_THRESHOLD:
        fan.on()
        print(f"Fan ON: Temp {temp:.1f}°C exceeds threshold {FAN_THRESHOLD}°C")
    else:
        fan.off()
        print(f"Fan OFF: Temp {temp:.1f}°C below threshold {FAN_THRESHOLD}°C")

def main():
    global fan
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        fan = DigitalOutputDevice(FAN_PIN, active_high=True, initial_value=False)
        print(f"Fan control initialized on GPIO{FAN_PIN} (BCM).")
    except GPIOZeroError as e:
        print(f"Error: Failed to initialize GPIO{FAN_PIN}: {e}")
        sys.exit(1)

    try:
        for i in range(READINGS):
            if not running:
                break
            temp = get_temperature()
            control_fan(temp, fan)
            time.sleep(PAUSE_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        if fan is not None:
            fan.close()
            print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

