import subprocess
import time
import signal
import sys
from gpiozero import PWMOutputDevice

# Constants
FAN_PIN = 14
PWM_FREQUENCY = 100
TEMP_THRESHOLDS = {
    70: 100,
    60: 85,
    50: 70,
    40: 50,
    32: 25,
    25: 15,
}

# Global state
fan = None
last_speed = None
running = True

def signal_handler(signum, frame):
    global running
    running = False

def get_cpu_temp():
    try:
        result = subprocess.run(
            ['vcgencmd', 'measure_temp'],
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode != 0:
            print(f"Error: vcgencmd failed (exit {result.returncode})")
            return None
        return float(result.stdout.strip().split('=')[1].split('=')[0])
    except subprocess.TimeoutExpired:
        print("Error: vcgencmd timed out")
        return None
    except Exception as e:
        print(f"Error reading CPU temperature: {e}")
        return None

def set_fan_speed(fan_device, temperature):
    if temperature is None:
        return
    for threshold, speed in TEMP_THRESHOLDS.items():
        if temperature >= threshold:
            fan_device.value = speed
            break
    else:
        fan_device.value = last_speed

def cleanup():
    global fan
    if fan is not None:
        fan.value = 0
        fan.close()

def main():
    global fan, last_speed
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQUENCY, initial_value=0)
    except Exception as e:
        print(f"Warning: Failed to initialize PWM on GPIO{FAN_PIN}: {e}")
        fan = None
        last_speed = None

    try:
        while running:
            temperature = get_cpu_temp()
            if temperature is not None:
                set_fan_speed(fan, temperature)
            else:
                print("Warning: Failed to read CPU temperature, keeping last speed.")
            time.sleep(5)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

