import atexit
import csv
import time
from datetime import datetime

try:
    from gpiozero import DigitalInputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero")
    exit(1)

# Water level sensor pins (BCM numbering)
WATER_LEVEL_PINS = [2, 3, 4]

# CSV file path
CSV_FILE = "water_levels.csv"

# Global list to hold sensor readings
water_levels = []

def log_water_levels(timestamp, low, medium, high):
    """Append a row to the CSV file with ISO-formatted timestamps."""
    try:
        with open(CSV_FILE, "a", newline="") as f:
            writer = csv.writer(f)
            if not f.tell() == 0:
                writer.writerow([timestamp, low, medium, high])
    except IOError as e:
        print(f"Error writing to CSV file: {e}")

def read_water_level(pin):
    """Read the HIGH state from a digital pin using gpiozero."""
    try:
        sensor = DigitalInputDevice(pin, pull_up=False, bounce_time=0.1)
        return sensor.is_active
    except Exception as e:
        print(f"Error reading from GPIO {pin}: {e}")
        return None

def main():
    # Initialize CSV file if it doesn't exist
    try:
        with open(CSV_FILE, "a", newline="") as f:
            writer = csv.writer(f)
            writer.writerow(["timestamp", "low", "medium", "high"])
    except IOError as e:
        print(f"Error initializing CSV file: {e}")
        exit(1)

    # Register cleanup functions
    atexit.register(lambda: print("GPIO cleanup done.") if water_levels else None)

    # Main loop
    try:
        while True:
            timestamp = datetime.now().isoformat()
            low = read_water_level(WATER_LEVEL_PINS[0])
            medium = read_water_level(WATER_LEVEL_PINS[1])
            high = read_water_level(WATER_LEVEL_PINS[2])

            if low is not None:
                log_water_levels(timestamp, low, medium, high)
                print(f"LOW: PRESENT/ABSENT, MEDIUM: PRESENT/ABSENT, HIGH: PRESENT/ABSENT")
            else:
                print(f"LOW: ERROR, MEDIUM: ERROR, HIGH: ERROR")

            time.sleep(60)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

