import signal
import sys
import time
import board
import busio
import adafruit_seesaw
from gpiozero import OutputDevice

# --- Configuration -----------------------------------------------------------
I2C_ADDR = 0x36
PUMP_PIN = 17
READ_INTERVAL = 10  # seconds
MOISTURE_THRESHOLD = 300  # soil-moisture-sensor-readings < 300 -> water-pump-on

# --- Globals for cleanup -----------------------------------------------------
_running = True
_pump = None
_i2c = None
_sensor = None


def _cleanup() -> None:
    """Turn off the pump and release all resources."""
    global _pump, _i2c, _sensor
    if _pump is not None:
        _pump.off()
        _pump.close()
        _pump = None
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
        _i2c = None
    if _sensor is not None:
        try:
            _sensor.deinit()
        except Exception:
            pass
        _sensor = None


def _signal_handler(signum, frame) -> None:
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
