import signal
import sys
import time

from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# Pin definitions (BCM numbering)
SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL = 1.0  # seconds

# Global list for cleanup
_sensors = []
_running = True


def _cleanup():
    """Release all GPIO resources."""
    for sensor in _sensors:
        try:
            sensor.close()
        except Exception:
            pass
    _sensors.clear()


def _signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for graceful shutdown."""
    global _running
    _running = False


def main():
    global _sensors, _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGTERM, _signal_handler)
    signal.signal(signal.SIGINT, _signal_handler)

    # Initialize all sensors with pull-up resistor (active-high)
    try:
        _sensors = [
            DigitalInputDevice(pin, pull_up=True, bounce_time=0.05)
            for pin in SENSOR_PINS
        ]
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"GPIO initialization error: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    print(f"Monitoring sensors on GPIO pins {SENSOR_PINS} every {POLL_INTERVAL}s. Press Ctrl+C to exit.")

    try:
        while _running:
            for sensor in _sensors:
                try:
                    if sensor.is_active:
                        print("Response for sensor {}".format(sensor.pin))
                except (GPIOZeroError, GPIODeviceError) as e:
                    print(f"Error reading sensor {sensor.pin}: {e}", file=sys.stderr)
            time.sleep(POLL_INTERVAL)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        _cleanup()
        print("GPIO cleanup complete.")


if __name__ == "__main__":
    main()

