import RPi.GPIO as GPIO
import time
import requests
import sys

# Configuration
POWER_PIN = 17
ALERT_URL = "http://example.com/alert"
ALERT_TIMEOUT = 5

def setup_gpio():
    """Configure GPIO pin 17 as input with pull-up resistor."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(POWER_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def read_power_status():
    """Read voltage level from GPIO pin. Returns True if power is present, False otherwise."""
    try:
        return GPIO.input(POWER_PIN) == GPIO.HIGH
    except Exception as e:
        print(f"Error reading power status: {e}")
        return False

def send_alert():
    """Send HTTP POST request to alert endpoint."""
    try:
        response = requests.post(ALERT_URL, json={"alert": "Power failure detected"}, timeout=ALERT_TIMEOUT)
        response.raise_for_status()
        print("Alert sent successfully.")
    except requests.exceptions.RequestException as e:
        print(f"Error sending alert: {e}")

def main():
    setup_gpio()
    print("Monitoring power status on GPIO 17. Press Ctrl+C to exit.")

    while True:
        status = read_power_status()
        if status:
            print("Power is present")
        else:
            print("Power failure detected")
            send_alert()
        time.sleep(1)

if __name__ == "__main__":
    main()

