#!/usr/bin/env python3
"""Flask web server for an LED on GPIO 17 (BCM) on a Raspberry Pi."""

import signal
import sys
from flask import Flask, render_template_string, request, redirect, url_for
from gpiozero import LED
from gpiozero.exc import GPIODeviceError, GPIOPinInUse

app = Flask(__name__)
LED_PIN = 17

# Module-level LED instance so it persists across requests
led = None

def cleanup(signum=None, frame=None):
    """Release GPIO resources on exit."""
    global led
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

# Register signal handlers for graceful shutdown
signal.signal(signal.SIGINT, cleanup)
signal.signal(signal.SIGTERM, cleanup)

@app.route('/')
def index():
    """Index page with ON/OFF links."""
    return render_template_string(
        """
        <html>
        <head><title>LED Control</title></head>
        <body>
            <h1>LED Control</h1>
            <a href="/light_on">Turn ON</a>
            <a href="/light_off">Turn OFF</a>
        </body>
        </html>
        """,
        ON=f"<p><a href='/light_on'>Turn ON</a></p>",
        OFF=f"<p><a href='/light_off'>Turn OFF</a></p>",
    )

@app.route('/light_on')
def light_on():
    """Turn the LED on."""
    if led is None:
        return redirect(url_for('index'))
    try:
        led.on()
        return redirect(url_for('index'))
    except GPIOPinInUse:
        return "Error: LED is already in use.", 400
    except GPIODeviceError as e:
        return f"Error: {e}", 500

@app.route('/light_off')
def light_off():
    """Turn the LED off."""
    if led is None:
        return redirect(url_for('index'))
    try:
        led.off()
        return redirect(url_for('index'))
    except GPIOPinInUse:
        return "Error: LED is already in use.", 400
    except GPIODeviceError as e:
        return f"Error: {e}", 500

if __name__ == '__main__':
    try:
        led = LED(LED_PIN)
    except GPIODeviceError as e:
        print(f"GPIO initialization error: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
        sys.exit(1)

    app.run(host='0.0.0.0', port=8080, debug=False)

