import socket
import logging
import signal
import sys
from gpiozero import OutputDevice

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

BACKLIGHT_PIN = 24
SERVER_PORT = 9100

running = True

def signal_handler(signum, frame):
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False

def handle_client(client_socket, backlight_pin):
    global running
    try:
        while running:
            try:
                raw = client_socket.recv(1024)
                if not raw:
                    break
                command = raw.decode('utf-8', errors='replace').strip()
                if command:
                    logging.info(f"Received command: {command}")
                    if command == 'on':
                        backlight_pin.on()
                        reply = 'backlight on'
                    elif command == 'off':
                        backlight_pin.off()
                        reply = 'backlight off'
                    else:
                        reply = 'unknown command'
                    client_socket.sendall(reply.encode('utf-8'))
            except socket.timeout:
                continue
            except Exception as e:
                logging.error(f"Error handling client: {e}")
    finally:
        client_socket.close()
        logging.info("Client closed.")

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        backlight_pin = OutputDevice(BACKLIGHT_PIN, initial_value=False)
        logging.info(f"GPIO initialized on pin {BACKLIGHT_PIN}.")
    except Exception as e:
        logging.error(f"Failed to initialize GPIO: {e}")
        sys.exit(1)

    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind(('0.0.0.0', SERVER_PORT))
        server_socket.listen(1)
        server_socket.settimeout(5)
        logging.info(f"Server listening on port {SERVER_PORT}.")
    except Exception as e:
        logging.error(f"Failed to create server socket: {e}")
        if backlight_pin:
            backlight_pin.close()
        sys.exit(1)

    try:
        while True:
            try:
                client_socket, client_address = server_socket.accept()
                logging.info(f"Connection from {client_address}")
                handle_client(client_socket, backlight_pin)
            except socket.timeout:
                continue
            except Exception as e:
                logging.error(f"Error handling client connection: {e}")
    finally:
        server_socket.close()
        logging.info("Server closed.")

if __name__ == "__main__":
    main()

