import signal
import sys
import time

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(1)

FAN_PIN = 12
PWM_FREQUENCY = 25000

fan = None
running = True

def signal_handler(signum, frame):
    global running
    running = False

def get_fan_speed():
    while True:
        try:
            raw = input("Enter fan speed (0-100): ").strip()
            if not raw.isdigit() or not 0 <= int(raw) <= 100:
                print("Invalid input. Please enter a number between 0 and 100.")
                continue
            return int(raw)
        except EOFError:
            print("\nEOF received. Exiting.")
            return None
        except ValueError:
            print("Invalid input. Please enter a number.")

def main():
    global fan
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQUENCY, initial_value=0)
    except GPIOZeroError as e:
        print(f"Error: Could not initialize GPIO {FAN_PIN} for hardware PWM: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing GPIO {FAN_PIN}: {e}")
        sys.exit(1)

    try:
        while running:
            speed = get_fan_speed()
            if speed is not None:
                try:
                    fan.value = speed / 100.0
                except GPIOZeroError as e:
                    print(f"Error setting PWM value: {e}")
            time.sleep(0.1)
    finally:
        if fan is not None:
            try:
                fan.value = 0
                fan.close()
            except Exception:
                pass
        print("Fan stopped. Exiting.")

if __name__ == "__main__":
    main()

