led = None

def cleanup(signum=None, frame=None):
    global led
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def handle_request(request, client_address):
    if request.method == 'GET':
        if '/led/on' in request.path:
            led.on()
            return http.server.HttpResponse(
                'LED is ON',
                mimetype='text/plain',
                headers={'Content-Length': len('LED is ON')}
            )
        elif '/led/off' in request.path:
