import atexit
import time
import signal
import logging
import sys

try:
    import board
    import busio
    from adafruit_pca9685 import PCA9685
except ImportError:
    logging.error("Required libraries not found. Please install: pip install adafruit-circuitpython-pca9685")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class Fuchikoma:
    def __init__(self, i2c_address=0x40, pwm_frequency=60, min_pulse_width=150, max_pulse_width=600):
        self.i2c_address = i2c_address
        self.pwm_frequency = pwm_frequency
        self.min_pulse_width = min_pulse_width
        self.max_pulse_width = max_pulse_width
        self.servo_channels = {}
        self.pwm_servo = None
        self._running = True

        try:
            self.i2c = busio.I2C(board.SCL, board.SDA)
            self.pwm_servo = PCA9685(self.i2c, address=self.i2c_address)
            self.pwm_servo.frequency = self.pwm_frequency
            self.pwm_servo.min_pulse_width = self.min_pulse_width
            self.pwm_servo.max_pulse_width = self.max_pulse_width
            logging.info(f"PCA9685 initialized at 0x{self.i2c_address:02X} at {self.pwm_frequency} Hz")
        except (ValueError, OSError) as e:
            logging.error(f"Failed to initialize PCA9685 at 0x{self.i2c_address:02X}: {e}")
            self.cleanup()
            sys.exit(1)

        atexit.register(self.cleanup)

    def move_servo(self, servo_name, angle, delay=0.029):
        if not self.servo_channels.get(servo_name):
            logging.error(f"Servo '{servo_name}' not found or not initialized.")
            return
        if not -77 <= angle <= 77:
            logging.error(f"Angle {angle} out of range for servo '{servo_name}'.")
            return
        try:
            pulse_width = self.pwm_servo.angle_to_pulse_width(angle)
            self.pwm_servo.angle = angle
            self.pwm_servo.angle_to_pulse_width(0)
            time.sleep(delay)
            self.pwm_servo.angle_to_pulse_width(pulse_width)
        except (ValueError, OSError) as e:
            logging.error(f"Error moving servo '{servo_name}': {e}")

    def bite(self):
        self.move_servo('claw', -75, delay=0.029)
        self.move_servo('lock', 75, delay=0.029)

    def open_claw(self):
        self.move_servo('claw', 75)

    def lock(self):
        self.move_servo('lock', 75)

    def unlock(self):
        self.move_servo('lock', -75)

    def shoot(self):
        self.move_servo('water_gun', -75, delay=0.029)
        time.sleep(0.15)
        self.load_water()

    def load_water(self):
        self.move_servo('water_gun', 75)

    def cleanup(self):
        if self.pwm_servo is not None:
            try:
                self.pwm_servo.angle_to_pulse_width(0)
                self.pwm_servo.angle = 0
                logging.info("PCA9685 channels deinitialized.")
            except (ValueError, OSError) as e:
                logging.error(f"Error deinitializing PCA9685: {e}")
        self.i2c.deinit()

    def signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received. Shutting down.")
        self._running = False

    def run(self):
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)
        try:
            while self._running:
                for servo_name in self.servo_channels:
                    if not self._running:
                        break
                    angle = self.servo_channels[servo_name].angle
                    if angle is not None:
                        self.move_servo(servo_name, angle)
                time.sleep(0.05)
        except KeyboardInterrupt:
            logging.info("KeyboardInterrupt received.")
        finally:
            self.cleanup()

if __name__ == "__main__":
    fuchikoma = Fuchikoma()
    fuchikoma.run()

