# Configuration
LED_PIN = 18
READING_COUNT = 5
READING_DELAY = 2  # seconds

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def simulate_water_quality_reading():
    """Simulate a water quality reading as a percentage (0-100)."""
    return random.randint(0, 100)


def control_led(led, reading):
    """Control the LED based on the simulated reading."""
    if reading < 50:
        led.on()
    else:
        led.off()


def main():
    """Main function to simulate water quality monitoring and control the LED."""
    global _running

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize LED on GPIO18 with error handling
    try:
        led = LED(LED_PIN)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error: Failed to initialize LED on GPIO{LED_PIN}: {e}")
        sys.exit(1)

    try:
        for i in range(READING_COUNT):
            if not _running:
                break

            reading = simulate_water_quality_reading()
            print(f"Reading {i + 1}/{READING_COUNT}: {reading}%")

            if reading < 50:
                control_led(led, reading)
                print("LED ON (water quality too low)")
            else:
                print("LED OFF (water quality normal)")

            if i < READING_COUNT - 1 and _running:
                time.sleep(READING_DELAY)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        # gpiozero handles cleanup automatically on close(), but we explicitly close
        # the LED to release the pin immediately.
        try:
            led.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

