import time
import random
import sys
from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# Configuration
SENSOR_PIN = 17          # BCM GPIO17 (active-low digital output)
SAMPLE_COUNT = 6         # Read 6 samples from the sensor
SAMPLE_INTERVAL = 0.3    # Seconds between readings
AVG_THRESHOLD = 7.5      # Threshold for maintenance alert

def read_sensor_state():
    """Return True if the sensor is LOW (vibration detected), False otherwise."""
    try:
        sensor = DigitalInputDevice(SENSOR_PIN, pull_up=True)
        return sensor.is_active
    except (GPIOZeroError, DeviceClosed) as e:
        print(f"Error reading sensor: {e}", file=sys.stderr)
        return False
    except Exception as e:
        print(f"Unexpected error reading sensor: {e}", file=sys.stderr)
        return False

def generate_amplitude():
    """Generate a random amplitude between 6.0 and 9.0."""
    return random.uniform(6.0, 9.0)

def main():
    """Main loop: read sensor, compute average, print alert or health status."""
    try:
        sensor = DigitalInputDevice(SENSOR_PIN, pull_up=True)
    except GPIOZeroError as e:
        print(f"Failed to initialize sensor on GPIO{SENSOR_PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing sensor: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(SAMPLE_COUNT):
            if not read_sensor_state():
                print("Sensor reading failed - skipping sample")
                time.sleep(SAMPLE_INTERVAL)
                continue

            amplitude = generate_amplitude()
            average = sum(amplitude) / SAMPLE_COUNT
            print(f"Sample {i+1}: Amplitude={amplitude:.2f}, Average={average:.2f}")

            if average > AVG_THRESHOLD:
                print("Maintenance recommended: wear trend is high")
            else:
                print("Component healthy: no action needed")

            time.sleep(SAMPLE_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram stopped by user")
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        sensor.close()
        print("GPIO resources released")

if __name__ == "__main__":
    main()

