import time
import random
import signal
import sys
from gpiozero import Button, OutputDevice

# Configuration constants
WATER_SENSOR_PIN = 17
PUMP_CONTROL_PIN = 18
WATER_LEVEL_THRESHOLDS = {
    20: "LOW",
    80: "HIGH",
    100: "HIGH"
}

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def simulate_water_level():
    """Simulate a water level reading between 0 and 100."""
    return random.randint(0, 100)

def control_pump(water_level):
    """Determine whether the pump should be on or off based on the water level."""
    if water_level < 20:
        return "ON"
    elif water_level > 80:
        return "OFF"
    else:
        return "ON"

def main():
    """Main simulation loop."""
    global _running

    # Register signal handlers for graceful termination
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize GPIO devices
    try:
        water_sensor = Button(WATER_SENSOR_PIN, pull_up=True, bounce_time=0.05)
        pump = OutputDevice(PUMP_CONTROL_PIN)
    except Exception as e:
        print(f"Error initializing GPIO devices: {e}")
        sys.exit(1)

    print("Water tank level monitoring system started. Press Ctrl+C to exit.")

    try:
        for iteration in range(5):
            if not _running:
                break

            water_level = simulate_water_level()
            pump_state = control_pump(water_level)

            print(f"Water Level: {water_level}% | Pump State: {pump_state}")

            # Wait for 2 seconds, checking for shutdown signal every 0.1s
            for _ in range(20):
                if not _running:
                    break
                time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error during simulation: {e}")
    finally:
        # Ensure pump is off and GPIO devices are released
        try:
            pump.off()
            pump.close()
        except Exception:
            pass
        try:
            water_sensor.close()
        except Exception:
            pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

