#!/usr/bin/env python3
"""
Wildlife tracking system with remote control via TCP socket.

Listens on 127.0.0.1:9099 for commands, reads GPS position, and
reports it as JSON.  Uses gpiozero for GPIO, pyserial for UART,
or smbus2 for I2C.  Falls back to simulated coordinates when no
module is available.
"""

import json
import signal
import sys
import socket
import time
from typing import Optional, Tuple

import serial
import serial.tools.list_ports

try:
    from gpiozero import OutputDevice
except ImportError:
    OutputDevice = None

try:
    import smbus2
except ImportError:
    smbus2 = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
HOST = "127.0.0.1"
PORT = 9099

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_gps_serial: Optional[serial.Serial] = None
_gps_i2c: Optional[smbus2.SMBus] = None
_socket: Optional[socket.socket] = None


def _signal_handler(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _cleanup() -> None:
    """Release all hardware resources."""
    global _gps_serial, _gps_i2c, _socket
    if _socket is not None:
        try:
            _socket.close()
        except Exception:
            pass
        _socket = None
    if _gps_serial is not None:
        try:
            _gps_serial.close()
        except Exception:
            pass
        _gps_serial = None
    if _gps_i2c is not None:
        try:
            _gps_i2c.close()
        except Exception:
            pass
        _gps_i2c = None


def _init_gps(port: str = "COM3", baudrate: int = 9600) -> Optional[serial.Serial]:
    """Initialize a GPS module via UART or I2C.

    Returns the serial port object, or None if the module is absent.
    """
    if port == "COM3":
        try:
            ser = serial.Serial(port=port, baudrate=baudrate, timeout=1)
            print(f"GPS initialized on COM{port} at {baudrate} baud.")
            return ser
        except serial.SerialException as exc:
            print(f"Error initializing GPS on COM{port}: {exc}", file=sys.stderr)
            return None
    elif port == "0x42":
        try:
            # I2C bus 0 is typically /dev/i2c-1 on Raspberry Pi.
            try:
                bus = smbus2.SMBus(1)
            except Exception:
                bus = None
            if bus is not None:
                try:
                    _gps_i2c = bus
                    print(f"GPS initialized on I2C bus 0 at 0x42.")
                    return bus
                except Exception as exc:
                    print(f"Error initializing I2C bus: {exc}", file=sys.stderr)
                    return None
            else:
                print("I2C bus unavailable; using simulated coordinates.", file=sys.stderr)
                return None
        except Exception as exc:
            print(f"Error initializing I2C bus: {exc}", file=sys.stderr)
            return None
    else:
        print(f"Unsupported GPS port: {port}", file=sys.stderr)
        return None


def _read_gps_position(gps_serial: Optional[serial.Serial] = None) -> Tuple[float, float]:
    """Read GPS position as (latitude, longitude) from UART.

    Returns (latitude, longitude) or (None, None) on failure.
    """
    if gps_serial is None:
        return None, None
    try:
        raw = gps_serial.readline()
        if not raw:
            return None, None
        line = raw.decode("ascii", errors="replace").strip()
        if not line:
            return None, None
        parts = line.split(",")
        if len(parts) != 3:
            return None, None
        lat = float(parts[0])
        lon = float(parts[1])
        return lat, lon
    except (ValueError, UnicodeDecodeError) as exc:
        print(f"Error reading GPS position: {exc}", file=sys.stderr)
        return None, None


def _handle_command(gps_serial: Optional[serial.Serial], command: str) -> None:
    """Process a single command from the GPS module."""
    if not command:
        return
    print(f"Received command: {command}")
    try:
        if command == "start":
            print("Tracking started.")
        elif command == "stop":
            print("Tracking stopped.")
        elif command == "report":
            lat, lon = _read_gps_position(gps_serial)
            if lat is not None and lon is not None:
                data = {"latitude": lat, "longitude": lon}
                print(json.dumps(data))
            else:
                print("Failed to read GPS position.", file=sys.stderr)
        else:
            print(f"Unknown command: {command}", file=sys.stderr)
    except Exception as exc:
        print(f"Error processing command: {exc}", file=sys.stderr)


def _init_gps_socket(host: str, port: int) -> Optional[socket.socket]:
    """Create a TCP socket for remote control."""
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(2.0)
        sock.connect((host, port))
        print(f"Connected to {host}:{port}")
        return sock
    except socket.error as exc:
        print(f"Error connecting to {host}:{port}: {exc}", file=sys.stderr)
        return None
    except Exception as exc:
        print(f"Unexpected error connecting to {host}:{port}: {exc}", file=sys.stderr)
        return None


def _cleanup_gps_socket(sock: Optional[socket.socket]) -> None:
    """Close the GPS socket if it was opened."""
    if sock is not None:
        try:
            sock.close()
            print("GPS socket closed.")
        except Exception as exc:
            print(f"Error closing GPS socket: {exc}", file=sys.stderr)


def main() -> None:
    """Main entry point."""
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # --- GPS initialization ---
    gps_serial = _init_gps()
    if gps_serial is None:
        print("Failed to initialize GPS module. Exiting.", file=sys.stderr)
        sys.exit(1)

    # --- Socket setup ---
    sock = _init_gps_socket(HOST, PORT)
    if sock is None:
        _cleanup_gps_socket(gps_serial)
        sys.exit(1)

    # --- Signal handlers for graceful shutdown ---
    def _shutdown(signum, frame):
        global _running
        _running = False
        print("\nShutdown requested.")
    signal.signal(signal.SIGINT, _shutdown)
    signal.signal(signal.SIGTERM, _shutdown)

    # --- Main loop ---
    try:
        while _running:
            try:
                sock.settimeout(2.0)
                conn, addr = sock.accept()
                print(f"Connection from {addr}")
                handle_command(gps_serial, conn.recv(1024).decode("utf-8", errors="replace"))
            except socket.timeout:
                continue
            except OSError as exc:
                print(f"Socket error: {exc}", file=sys.stderr)
                continue
            except Exception as exc:
                print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
                continue

    except Exception as exc:
        print(f"Fatal error in main loop: {exc}", file=sys.stderr)
    finally:
        _cleanup_gps_socket(sock)
        _cleanup()


if __name__ == "__main__":
    main()

