import time
import random
import signal
import sys

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(1)

PUMP_PIN = 17
MOISTURE_THRESHOLD = 30
NUM_ITERATIONS = 5
DELAY_SECONDS = 2

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def generate_moisture_reading():
    return random.randint(0, 100)

def control_pump(pump, moisture_reading):
    if moisture_reading < MOISTURE_THRESHOLD:
        pump.on()
        print(f"Moisture {moisture_reading} is too low. Pump ON.")
    else:
        pump.off()
        print(f"Moisture {moisture_reading} is sufficient. Pump OFF.")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        pump = OutputDevice(PUMP_PIN)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error: Failed to initialize GPIO {PUMP_PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing GPIO {PUMP_PIN}: {e}")
        sys.exit(1)

    try:
        for i in range(NUM_ITERATIONS):
            if not _running:
                break
            moisture = generate_moisture_reading()
            control_pump(pump, moisture)
            print(f"Iteration {i + 1}/{NUM_ITERATIONS}: "
                  f"Moisture {moisture} -> Pump {pump.value}")
            if _running:
                time.sleep(DELAY_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        try:
            pump.off()
            pump.close()
        except Exception:
            pass
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

