"""
Automated bird-feeder refill system for Raspberry Pi Zero W.
Uses two HC-SR04 ultrasonic distance sensors and a relay-controlled auger.
"""

import time
import logging
import signal
import sys
import threading
from gpiozero import DistanceSensor, OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# Configuration
SENSOR_A_TRIGGER_PIN = 17
SENSOR_A_ECHO_PIN = 18
SENSOR_B_TRIGGER_PIN = 22
SENSOR_B_ECHO_PIN = 23
RELAY_PIN = 27
SENSOR_A_THRESHOLD = 10.0  # cm
SENSOR_B_THRESHOLD = 15.0  # cm
COOLDOWN_SECONDS = 60
READING_WINDOW_SIZE = 3
RETRY_DELAY = 5
MAX_RETRIES = 3

