#!/usr/bin/env python3
"""
RC car controller using a PCA9685 PWM controller on a Raspberry Pi.

Controls:
  - Throttle (channel 0)
  - Steering (channel 1)
  - Reset (q)
  - Exit (x)

Wiring:
  - PCA9685 SDA -> GPIO2 (I2C bus 1, SDA), GPIO3 (I2C bus 1, SCL)
  - PCA9685 VCC -> 3.3 V, GND -> GND
  - ESC PWM_CHANNEL_ESC -> ESC output (typically 3.3 V)
  - ESC PWM_CHANNEL_STEERING -> steering output (typically 3.3 V)
"""

import signal
import sys
import time

import curses
from PIL import Image, ImageDraw, ImageFont

try:
    import board
    import busio
    from adafruit_pca9685 import PCA9685
except ImportError as exc:
    print(f"Missing dependency: {exc}", file=sys.stderr)
    print("Install with: pip install adafruit-circuitpython-pca9685", file=sys.stderr)
    sys.exit(0)

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
I2C_BUS = 1
PCA9685_ADDR = 0x40
PWM_CHANNEL_ESC = 0
PWM_CHANNEL_STEERING = 1
THROTTLE_STOP_VALUE = 400
STEERING_CENTER_VALUE = 500
ESC_RAMP_INC = 20
ESC_RAMP_DELAY = 0.1
ESC_RESET_VALUE = 400
ESC_STEERING_MIN = 380
ESC_STEERING_MAX = 620
ESC_STEERING_CENTER = 500

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_pwm = None
_i2c = None
_screen = None


def _cleanup():
    """Reset the ESC and steering to safe defaults."""
    global _pwm, _i2c, _screen
    try:
        if _pwm is not None:
            _pwm.set_pwm_duty_cycle(PWM_CHANNEL_ESC, ESC_RESET_VALUE)
            _pwm.set_pwm_duty_cycle(PWM_CHANNEL_STEERING, ESC_RESET_VALUE)
    except Exception:
        pass
    try:
        if _i2c is not None:
            _i2c.deinit()
    except Exception:
        pass
    try:
        if _screen is not None:
            _screen.erase()
            _screen.refresh()
    except Exception:
        pass


def _signal_handler(signum, frame):
    global _running
    _running = False


def _init_i2c():
    """Initialize the I2C bus and PCA9685."""
    global _i2c
    try:
        _i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"I2C init error: {exc}", file=sys.stderr)
        sys.exit(0)

    try:
        _pwm = PCA9685(_i2c, address=PCA9685_ADDR)
    except Exception as exc:
        print(f"PCA9685 init error: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(0)

    # Calibrate ESC on channel 0
    print("Calibrating ESC on channel 0...")
    for _ in range(ESC_RAMP_INC):
        try:
            _pwm.set_pwm_duty_cycle(PWM_CHANNEL_ESC, ESC_RAMP_INC)
            _pwm.set_pwm_duty_cycle(PWM_CHANNEL_ESC, ESC_RAMP_INC)
        except Exception as exc:
            print(f"Calibration error: {exc}", file=sys.stderr)
            _cleanup()
            sys.exit(0)
        time.sleep(ESC_RAMP_DELAY)
    try:
        _pwm.set_pwm_duty_cycle(PWM_CHANNEL_ESC, ESC_RAMP_INC)
    except Exception as exc:
        print(f"Calibration error: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(0)

    # Set initial throttle and steering
    try:
        _pwm.set_pwm_duty_cycle(PWM_CHANNEL_ESC, ESC_RESET_VALUE)
        _pwm.set_pwm_duty_cycle(PWM_CHANNEL_STEERING, ESC_RESET_VALUE)
    except Exception as exc:
        print(f"Initialization error: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(0)

    print("RC car controller initialized.")


def _init_curses():
    """Initialize the curses terminal for keyboard input."""
    global _screen
    try:
        _screen = curses.initscr()
        curses.noecho()
        curses.cbreak()
        _screen.keypad(True)
        _screen.nodelay(True)
    except curses.error as exc:
        print(f"curses init error: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(0)

    return _screen


def _init_font():
    """Load a monospaced font for the curses display."""
    try:
        font = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 12)
        return ImageFont.truetype(font, 12)
    except Exception as exc:
        print(f"Font init error: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(0)


def _draw_text(screen, text, y, font):
    """Draw a string at y on the curses screen."""
    try:
        screen.addstr(y, 0, text)
    except curses.error as exc:
        print(f"Draw error: {exc}", file=sys.stderr)


def _draw_arrow(screen, x, y, direction):
    """Draw an arrow pointing in direction on the curses screen."""
    try:
        if direction == "up":
            screen.addch(y, x, curses.ACS_UPPERCASE)
        elif direction == "down":
            screen.addch(y, x, curses.ACS_LOWERCASE)
        elif direction == "left":
            screen.addch(y, x, curses.ACS_DLINE)
