    except Exception as exc:
        print(f"I2C init error: {exc}", file=sys.stderr)
        sys.exit(0)

    try:
        _pwm = PCA9685(_i2c, address=PCA9685_ADDR)
    except Exception as exc:
        print(f"PCA9685 init error: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(0)

    # Calibrate ESC on channel 0
    print("Calibrating ESC on channel 0...")
