import json
import signal
import sys
import logging
from flask import Flask, request, jsonify
from gpiozero import OutputDevice

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

app = Flask(__name__)
relay = None

def cleanup(signum=None, frame=None):
    global relay
    if relay is not None:
        try:
            relay.close()
            logger.info("GPIO cleanup complete.")
        except Exception as e:
            logger.error(f"Error during GPIO cleanup: {e}")
    sys.exit(0)

signal.signal(signal.SIGINT, cleanup)
signal.signal(signal.SIGTERM, cleanup)

@app.route('/relay', methods=['POST'])
def relay_control():
    try:
        payload = request.get_json()
        if not payload or 'state' not in payload:
            return jsonify({'error': 'Invalid request: missing or malformed JSON'}), 400
        state = payload['state']
        if state not in ('on', 'off'):
            return jsonify({'error': 'Invalid state value. Must be "on" or "off"'}), 400
        relay.value = state
        return jsonify({'status': 'Relay state changed'}), 200
    except Exception as e:
        logger.error(f"Error processing relay request: {e}")
        return jsonify({'error': 'Internal server error'}), 500

if __name__ == '__main__':
    try:
        relay = OutputDevice(23, active_high=True, initial_value=False)
        logger.info("Relay initialized on GPIO23 (BCM).")
    except Exception as e:
        logger.error(f"Failed to initialize GPIO: {e}")
        sys.exit(1)
    app.run(host='0.0.0.0', port=5000, debug=False)

