import logging
import signal
import sys
from gpiozero import OutputDevice

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Define the actuator GPIO pins using gpiozero OutputDevice
PUMP_PIN = 20
LIGHT_PIN = 21

# Define the intents that the parser can recognize
INTENT_MAP = {
    "pump_on": "turn the pump on",
    "pump_off": "turn the pump off",
    "light_toggle": "turn the light",
    "unknown": "unknown command"
}

# Global list to hold the actuators for cleanup
actuators = []

def initialize_actuators():
    """Initializes the gpiozero OutputDevice actuators for the pump and light."""
    try:
        pump = OutputDevice(PUMP_PIN)
        light = OutputDevice(LIGHT_PIN)
        actuators.append(pump)
        actuators.append(light)
        logging.info("Actuators initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize actuators: {e}")
        raise

def cleanup_actuators(signum=None, frame=None):
    """Shuts down the actuators and releases the GPIO resources."""
    logging.info("Cleaning up actuators...")
    for act in actuators:
        try:
            act.close()
        except Exception as e:
            logging.warning(f"Error closing actuator: {e}")
    actuators.clear()
    if signum is not None:
        sys.exit(0)

def parse_phrase(phrase):
    """Parses a plain English phrase into a hydroponics control intent."""
    try:
        intent = INTENT_MAP.get(phrase.lower(), "unknown")
        logging.info(f"Parsed phrase: {phrase} -> {intent}")
        return intent
    except KeyError:
        logging.warning(f"Unknown phrase: {phrase}")
        return "unknown"

def main():
    """Main function to parse and control the hydroponics system."""
    initialize_actuators()

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup_actuators)
    signal.signal(signal.SIGTERM, cleanup_actuators)

    try:
        while True:
            try:
                phrase = input("Enter a hydroponics control phrase: ")
            except EOFError:
                logging.info("End of input reached. Exiting.")
                break

            parsed_intent = parse_phrase(phrase)

            if parsed_intent == "pump_on":
                actuators[0].on()
                logging.info("Pump turned on.")
            elif parsed_intent == "pump_off":
                actuators[0].off()
                logging.info("Pump turned off.")
            elif parsed_intent == "light_toggle":
                actuators[1].toggle()
                logging.info("Light turned on/off.")
            else:
                logging.warning(f"Unknown intent: {parsed_intent}")
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup_actuators()

if __name__ == "__main__":
    main()

