import signal
import sys
import time
from gpiozero import LED, Servo, Button
from gpiozero.pins.native import NativeFactory

# Pin definitions (BCM numbering)
LED_PIN = 14
SERVO_PIN = 18
BUTTON_PIN = 15

# Servo parameters
SERVO_FREQ = 50  # Hz
SERVO_MIN_PULSE = 1.0 / (2 ** 15)  # ~1.0 ms
SERVO_MAX_PULSE = 2.0 / (2 ** 15)  # ~2.0 ms
SERVO_DEBOUNCE = 0.1  # seconds

# Global state
led = None
servo = None
button = None
running = True

def cleanup():
    """Release all resources cleanly."""
    global led, servo, button
    if servo is not None:
        try:
            servo.value = 0.0
            servo.close()
        except Exception:
            pass
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
    if button is not None:
        try:
            button.close()
        except Exception:
            pass
    print("Cleanup complete.")

def handle_button_press():
    """Handle a single button press."""
    global led, servo, button
    if led is None or servo is None:
        return
    try:
        if button.is_pressed:
            led.on()
            servo.angle = 20.0
            servo.value = SERVO_MIN_PULSE
            time.sleep(SERVO_DEBOUNCE)
            if servo.angle > 180.0:
                servo.angle = 180.0
                print("Servo angle reset to 180 degrees.")
            else:
                print("Servo angle set to 20 degrees.")
        else:
            led.off()
    except Exception as e:
        print(f"Error during button press: {e}")

def main():
    global led, servo, button, running

    # Use native pin factory for better performance (no daemon thread)
    try:
        NativeFactory.pin_factory = None
    except Exception:
        pass

    # Initialize GPIO devices
    try:
        led = LED(LED_PIN)
        servo = Servo(SERVO_PIN, frequency=SERVO_FREQ, initial_value=0.0)
        button = Button(BUTTON_PIN, pull_up=True, bounce_time=0.05)
    except Exception as e:
        print(f"Failed to initialize GPIO devices: {e}")
        cleanup()
        sys.exit(1)

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Main loop
    try:
        while running:
            handle_button_press()
            time.sleep(0.1)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

