import serial
import time
import signal
import sys
import logging
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'co2_readings_log.txt'
SAMPLE_INTERVAL = 5

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler(LOG_FILE),
        logging.StreamHandler(sys.stdout)
    ]
)

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_co2_level(ser):
    try:
        raw = ser.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except (serial.SerialException, ValueError, IOError) as e:
        logging.error(f'Serial read error: {e}')
        return None
    except Exception as e:
        logging.error(f'Unexpected read error: {e}')
        return None

def log_co2_level(co2_level):
    if co2_level is None:
        return
    timestamp = datetime.now().isoformat(timespec='seconds')
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(f'{timestamp} - CO2 Level: {co2_level} ppm\n')
    except IOError as e:
        logging.error(f'Failed to write to log file: {e}')

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=TIMEOUT
        )
        logging.info(f'Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.')

        while _running:
            co2_level = read_co2_level(ser)
            if co2_level is not None:
                log_co2_level(co2_level)
            else:
                logging.warning('CO2 level read failed; skipping this sample.')

            if _running:
                time.sleep(SAMPLE_INTERVAL)

    except serial.SerialException as e:
        logging.error(f'Serial port error: {e}')
    except IOError as e:
        logging.error(f'I/O error: {e}')
    except Exception as e:
        logging.error(f'Unexpected error: {e}')
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            logging.info('Serial port closed.')
        logging.info('Program terminated.')

if __name__ == '__main__':
    main()

