import serial
import time
import signal
import sys
from gpiozero import OutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def parse_radiation_level(line: str) -> float | None:
    """Parse a single line of radiation data, returning None on error."""
    try:
        return float(line)
    except ValueError:
        print(f"Warning: non-numeric data received: '{line}'")
        return None

def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT,
        )
    except serial.SerialException as e:
        print(f"Error: cannot open serial port {SERIAL_PORT}: {e}")
        return 1

    try:
        alarm = OutputDevice(ALARM_PIN, active_high=True, initial_value=False)
    except Exception as e:
        print(f"Error: failed to initialize GPIO {ALARM_PIN}: {e}")
        try:
            ser.close()
        except Exception:
            pass
        return 1

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Error: serial read failed: {e}")
                break

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            radiation = parse_radiation_level(line)
            if radiation is not None:
                if radiation > RADIATION_THRESHOLD:
                    alarm.on()
                else:
                    alarm.off()
            time.sleep(READ_INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        try:
            alarm.close()
        except Exception:
            pass
        print("Resources released. Exiting.")
    return 0

if __name__ == "__main__":
    sys.exit(main())

