BAUD_RATE = 9600
READ_TIMEOUT = 1.0
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
ALARM_ACTIVE = True
ALARM_INACTIVE = False

running = True

def signal_handler(signum, frame):
    global running
    running = False

def parse_radiation_level(line):
    if not line:
        return None
    try:
        return float(line)
    except ValueError:
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
        sys.exit(1)

    try:
        alarm = OutputDevice(ALARM_PIN, active_high=True, initial_value=False)
    except GPIOZeroError as e:
        print(f"Error initializing GPIO pin {ALARM_PIN}: {e}")
        ser.close()
        sys.exit(1)

    try:
        while running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial I/O error: {e}")
                time.sleep(1)
                continue

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            radiation = parse_radiation_level(line)
            if radiation is not None:
                if radiation > RADIATION_THRESHOLD:
                    alarm.on()
                    print(f"Radiation level: {radiation:.2f} µSv/h")
                else:
                    alarm.off()
                    print(f"Radiation level: {radiation:.2f} µSv/h")
                print(f"Alarm state: {ALARM_INACTIVE if ALARM_ACTIVE else ALARM_ACTIVE}")
            else:
                print(f"Invalid data received: {line!r}")

            time.sleep(1)

    finally:
        try:
            alarm.off()
            alarm.close()
        except Exception:
            pass
        try:
            ser.close()
        except Exception:
            pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

