class SimpleGPS:
    def __init__(self, port='/dev/serial0', baudrate=9600, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_connection = None
        self._running = True

    def connect(self):
        try:
            self.serial_connection = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout
            )
            logging.info(f"Connected to GPS on {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            return False
        except OSError as e:
            logging.error(f"OS error opening serial port {self.port}: {e}")
            return False

    def read_data(self):
        if self.serial_connection is None:
            return None
        try:
            if self.serial_connection.in_waiting > 0:
                raw_data = self.serial_connection.readline()
                if raw_data:
                    return raw_data.decode('utf-8', errors='ignore').strip()
                return None
            return None
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            return None
        except OSError as e:
            logging.error(f"OS error during read: {e}")
            return None

    def parse_gga(self, sentence):
        if not sentence:
            return None
        try:
            if sentence.startswith('$GPGGA'):
                parts = sentence.split(',')
                if len(parts) < 6:
                    return None
                utc_time = parts[1]
                latitude = parts[2]
                longitude = parts[3]
                fix_quality = parts[4]
                num_satellites = parts[5]
                return {
                    'utc_time': utc_time,
                    'latitude': latitude,
                    'longitude': longitude,
                    'fix_quality': fix_quality,
                    'num_satellites': num_satellites
                }
            elif sentence.startswith('$GNGGA'):
                parts = sentence.split(',')
                if len(parts) < 6:
                    return None
                utc_time = parts[1]
                latitude = parts[2]
                longitude = parts[3]
                fix_quality = parts[4]
                num_satellites = parts[5]
                return {
                    'utc_time': utc_time,
                    'latitude': latitude,
                    'longitude': longitude,
                    'fix_quality': fix_quality,
                    'num_satellites': num_satellites
                }
            else:
                return None
        except (IndexError, ValueError) as e:
            logging.error(f"Invalid GGA/GGN sentence format: {e}")
            return None

    def close(self):
        if self.serial_connection and self.serial_connection.is_open:
            try:
                self.serial_connection.close()
                logging.info("Serial connection closed.")
            except serial.SerialException as e:
                logging.error(f"Error closing serial connection: {e}")
        self.serial_connection = None

    def __del__(self):
        self.close()


def main():
    gps = SimpleGPS()
    running = True

    def signal_handler(sig, frame):
        nonlocal running
        logging.info("Signal received, shutting down...")
        running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not gps.connect():
        logging.error("Failed to connect to GPS. Exiting.")
        sys.exit(1)

