                    logging.info(f"Parsed: {parsed}")
            else:
                logging.warning("No data available to parse.")
            time.sleep(0.1)
    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    finally:
        gps.close()


if __name__ == "__main__":
