import serial
import serial.tools.list_ports
import serial.SerialException
import threading
import time
import signal
import sys

app = Flask(__name__)

PORT = '/dev/ttyUSB0'
BAUD = 9600
TIMEOUT = 1

serial_lock = threading.Lock()
serial_port = None
serial_running = False

shutdown_event = threading.Event()


def open_serial(port, baudrate):
    global serial_port, serial_running
    try:
        serial_port = serial.Serial(
            port=port,
            baudrate=baudrate,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
            write_timeout=TIMEOUT,
        )
        serial_running = True
        print(f"Serial port {port} opened at {baudrate} baud.")
        return serial_port
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}")
        serial_port = None
        serial_running = False
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}")
        serial_port = None
        serial_running = False
        return None


def send_command(serial_port, cmd):
    if serial_port is None or not serial_running:
        return False
    try:
        serial_port.write(cmd.encode('ascii'))
        serial_port.flush()
        return True
    except serial.SerialException as e:
        print(f"Serial write error: {e}")
        return False
    except Exception as e:
        print(f"Unexpected serial error: {e}")
        return False


def receive_line(serial_port):
    if serial_port is None or not serial_running:
        return None
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial read error: {e}")
        return None
    except Exception as e:
        print(f"Unexpected serial error: {e}")
        return None


def close_serial(serial_port):
    if serial_port is not None and serial_running:
        try:
            if serial_port.is_open:
                serial_port.close()
                print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}")
        finally:
            serial_port = None
            serial_running = False


def get_serial_info():
    try:
        ports = [p.device for p in serial.tools.list_ports.comports()]
        if not ports:
            return "No serial ports found."
        return f"Available serial ports: {ports}"
    except serial.SerialException as e:
        return f"Error listing serial ports: {e}"
    except Exception as e:
        return f"Unexpected error listing serial ports: {e}"


def get_serial_data():
    try:
        info = get_serial_info()
        if info.startswith("Available serial ports:"):
            return info.split(":")[1].strip()
        return info
    except Exception as e:
        return f"Error getting serial data: {e}"


def create_serial_data(name, done):
    if not name or not done:
        return "Invalid input. Name must be non-empty and done must be boolean."
    try:
        serial_port = open_serial(PORT, BAUD)
        if serial_port is None:
            return "Failed to open serial port."
        serial_port.write(f"{name}\n".encode('ascii'))
        serial_port.flush()
        serial_port.close()
        print(f"Serial data created: {name} (done={done})")
        return f"Serial data created: {name} (done={done})"
    except serial.SerialException as e:
        print(f"Error creating serial data: {e}")
        return "Failed to create serial data."
    except Exception as e:
        print(f"Unexpected error creating serial data: {e}")
        return "Failed to create serial data."


def get_serial_data_by_id(id):
    try:
        data = get_serial_data()
        parts = data.split("\n")
        if len(parts) < 2:
            return None
        return parts[1]
    except Exception as e:
        return f"Error getting serial data by ID: {e}"


def get_serial_data_by_id_int(id):
    try:
        data = get_serial_data_by_id(id)
        if data is None:
            return None
        return data.split("\n")[0]
    except Exception as e:
